INSERT INTO lan391_practice_image_map (
    expression_id, scenario_id, expression_display_order, sql_values_row,
    example3_sentence, example4_sentence, example3_sha256, example4_sha256
) VALUES
    (4001, 44, 1, 1, 'I play basketball with my brother.', 'I play badminton every Sunday.', 'ab8686c3ea7e377a4205721ef24e3e7592b521491b8175c0927067212acbc5fb', '7118db02abf163d6703b6cd443ddc6f9aba913f7f8465b66e1f88eaf1e2e88ee'),
    (4002, 44, 2, 2, 'Do I need special shoes?', 'Do I need a pen?', '27d81e8af8e96b61b3d7657d4ef3af7539d7f168507cc11dae32cb3f5d0d233a', '5340d3b357477e6f996e410a65618718318692594bdb172b76757254a1dea042'),
    (4003, 44, 3, 3, 'That sounds fun. Can I join?', 'That sounds fun. I will watch it.', '6379c9528aef958c784f397fdabcbc965a225f097263613438771ee3fc54d610', '1106dc7d604dd877326144fac9e7f5567e3da2774b25f0e5dd959a73efd78404'),
    (4004, 44, 4, 4, 'I''ll be there at two.', 'I won''t. I''ll be there.', '782e007c66df6425bb7ce06de01209b5e18fa6579c183f0201b57a6b3aaaf71c', 'c27d8157dc7e5761d25af92482bf531f32cd3ecbc4a6324e09c816639d27a6f2'),
    (4005, 44, 5, 5, 'I''m looking for a small group with friendly people.', 'I''m looking for a sport I can start from zero.', 'c5affe52dfd4ed5cfed2912fe95ae95717634851bbc4f5e992ea121da680bb46', 'c35d4a4fe55e7711b4aec9ba842c9fa02a0c8f6a8fe50da9e69c5dc958e238c9'),
    (4006, 44, 6, 6, 'That makes me nervous. I''m a total beginner.', 'I''m a total beginner, so please explain them slowly.', 'ca3bcb426cf4145765ff7aecfa4b9b93b7979cddb121848004155569c9df4b8b', '1733307f3ac9a8e73239f882ebf5ca6968ddfa534c90ca605d8af9aff1cecbe9'),
    (4007, 44, 7, 7, 'What should I bring for everyone?', 'Okay. What should I bring besides my shoes?', 'f4eb1d67de4635f7e6830870114a721cc79d55ea1beb8e187f1860472da40755', 'dce1fe858b3fafceb05c0f2291d676c562b8dd4115a73169c449c5f33661678b'),
    (4008, 44, 8, 8, 'Yes, I decided to give it a try.', 'I''ll give it a try for one month first.', 'aa5be0cef529d735e56afbce46d345b6d58932024d6c12f7065bdb1bc1f00a59', '48a3efb1d7d93cff75d9e6f0864c2b3486cbc3b2239a0a7ba46f8a90e4e52846'),
    (4009, 44, 9, 9, 'So, what do you say we take a break?', 'One more game — what do you say?', '7099eec6c24fbeae97658a8f965bf37714427f054b19f74d2afd546625cc4514', 'ce53e0d538c5e272af0bdb608e79e786db9e7ad45a15cbabdda2a1d1ef673aba'),
    (4010, 44, 10, 10, 'I want to be part of something bigger.', 'Thanks for letting me be part of this.', '15b566455d94d0be9afc2dae649f39d5b7959e1cecce08ac6edb7e16c88c94d0', 'ef408e72041fc9d0caf21414987728b388669a1f8c76773be348da2d7adc7629'),
    (4011, 44, 11, 11, 'We wouldn''t miss the final game — see you there.', 'I wouldn''t have missed that concert for the world.', 'aa60f2710b730756265c5f25c18afd370e852de7a650efd10bd58399a43f2dc3', 'aa2143c7d64d2060ba8ff5ae7ce30c80b7eeb5ecf2e03972dc73aef894a2b8ec'),
    (4012, 41, 1, 12, 'You will like the pork here.', 'You will like the tofu dish.', '000d7d0d95d00fce782a1b5eff112d267ff40106e30a730eca346a98558d8489', '86d6809613ae94224eec6da9debdd80fec2b572c2152cbc5c26b06cee3c74144'),
    (4013, 41, 2, 13, 'Let''s try the peach drink.', 'Let''s try a small size next time.', '08ebcd2861e698ddd2c8a9205c10c72b0b8d1a1984e5675ab826d0e22cb603f7', '772822ede7725d35bfa890d10bbf54464ee10a27eb41b4ab63ec0d5436f859a5'),
    (4014, 41, 3, 14, 'It is a little spicy but very good.', 'Maybe not. It is a little spicy.', 'b2319c49728e828ae8db0a6c3f7d505b10055c4ce8042adc79d86c390c3a52f0', '22c1b22a2c5fa8772ef7ef640fe9f4ad4750db8c86f9967cb5a829c28e855a50'),
    (4015, 41, 4, 15, 'Mix the two sauces together first.', 'Mix everything together with this spoon.', '09c811bc9065f0e67cc95460b11feda64de09e310d39693370891e1c6d0311d8', '60c78ec5d6949b8bd0af47a51a538615cfdeb828efbb93683766dc172a7db7a5'),
    (4016, 41, 5, 16, 'Yes, this restaurant is known for its grilled pork.', 'Busan is known for fresh fish, so try that.', '03bd7d38907a66b3c2f513a08c5f8136457b2258bccca8b83854cfbc6c05c3cc', 'd811b80ece788b73c907ebddcdfa77e1c8674c2af0af8f0226345ebcaf05e71b'),
    (4017, 41, 6, 17, 'Get the soy sauce one; it''s less spicy than the red one.', 'White kimchi is less spicy than normal kimchi.', 'af5c58db962b809dfd9774695061c413c5cd2c4a75743150a77442835748e9ff', 'bef1b89a133978d571ff25b1eba0a8a698afeefe6c7120310ba67b33c418d416'),
    (4018, 41, 7, 18, 'Pour it a little at a time, or it gets salty.', 'Drink some water and eat rice a little at a time.', 'af27d3b0a1b9deda70b992f74bad28eec6c6ed5f0e8de5f9d3dda892c347b66b', '955220f37f135e20f660352fa45596b582145d0a48580969e1394f45c69a317b'),
    (4019, 41, 8, 19, 'Wrap the rest in foil and take it home.', 'Then wrap the chicken in this paper.', 'e34bebed0dc31d1e75f39fdbb2f7232b60fca3f879cfcf99bcf2afa44a0cb971', '45cafc08fc4ef606e526a2253a91669e1198a15779b93b8b1a77590399d924ad'),
    (4020, 41, 9, 20, 'His jokes were real crowd-pleasers last night.', 'That film isn''t a crowd-pleaser, but I loved it.', '63de9072b10301ee9483070fc2a4fb078ec8cc3dcfb9492fa105ef8a5fff399d', 'ba7285503ff7c7b507c3c4cb13b9c733adbceb1b9b28645a2c9d5e2c19a66631'),
    (4021, 41, 10, 21, 'The kids dug in without waiting.', 'Help yourself and dig in!', '83cf9950c9a7debd6def9e7347330bcd379215a8e6940f3aaf3020bf7373b26f', '6164a081215e3241e96f70d1a1377bc890a7b19964087ae2a032ed275485bdbc'),
    (4022, 41, 11, 22, 'She washed her pills down with water.', 'Fries washed down with a cold soda — perfect.', 'dba867c73a912b836d416388a5578b50f9e97cbb6f132cb822c62ea9fbc5b4e6', '77c3fe62d0631923f6a45c7bf210f4f664ef6cad7c0eccec3c956c0ffb18386e'),
    (4023, 47, 1, 23, 'I like that idea. Let''s practice.', 'I like that idea. He has many friends.', 'bad7eec09c2356fbca75a7ffa15c4b936dd521bc6a27d5a6568df6a9e9bb0df0', 'd8a7d654125b8e6e56f24264845871e2ba5c9f851fa3500393d441a006bd7366'),
    (4024, 47, 2, 24, 'A hat. It is a surprise for him.', 'We are making a surprise for him.', '255c63f2324f57fe6f6a316f6daad93fc9b038bab3e5334ed446a080172c6085', '3b4aab8121f0f24bf10f4b4e64b41f023e8ccca60fb42181b852101f2bdce9cc'),
    (4025, 47, 3, 25, 'I can buy some juice.', 'Not yet. I can buy a small gift.', '867802e26a1d2e3d8590cdacbfcca48d34835a37da7f621a528c09cfb8912c86', 'a3c355da74cee02a70f16b6c6302cdeb6e5ff117b62e3d76bb5059f9425e4254'),
    (4026, 47, 4, 26, 'I can''t say. It''s a secret.', 'Say nothing. It''s a secret.', 'b158104e0be68f47f01bbec006d7b2968b1012948fad3d603b19a6032ddffe34', '9213e28f97d4d4be8fa1e659c3ef4ad57f92b3dab35772b75911139aee025a14'),
    (4027, 47, 5, 27, 'That sounds like fun. The photos will be great.', 'That sounds like fun. Let''s order two.', 'a6a3e98f32c295c280a62511ec34f7cb8db3630c9b2552fd0e0a463e5daf6d3c', '5ba48df80e127295e7f9cd9e5a4c97600f00cbc0d69e906592cba690a1b245a3'),
    (4028, 47, 6, 28, 'I''ll handle the cake order before my class.', 'I''ll handle the cleaning, don''t worry.', '5413b2de7c553e23c7572a47b27a334a6cda1da166c39f560668fb12e6adda42', 'ab2bfe4c4236987d02709755190d94766cd4ee5f057803d57aace656e8ca5d27'),
    (4029, 47, 7, 29, 'Make an excuse about the noise from next door.', 'I''ll make an excuse and take him shopping.', '57761498d561cbab6790fafdffe2205f9b791b179eb1a6540512a22adff17bf2', '5980a8aff7023d5bedc946b31a37fba31b567b92603b272f9cfe929625639dab'),
    (4030, 47, 8, 30, 'Pretend to be asleep on the sofa.', 'Pretend to be busy with homework.', 'f3cee25b7b7f61af45fa5a4df827212717a10b203d82baffae693722b54145b4', '58e54efcce2fd31dc21596e4830712423297479435cc0b4a082bf4f935fdfff2'),
    (4031, 47, 9, 31, 'She acted natural even though she knew everything.', 'Can you act natural for five more minutes?', '6a8963134f5f3a601596313a18ee30b7af35d3bab674d84a80404d811099ed2e', '2c384bc63ce8cfe65684ff9d2f6c93dcd5b103e29e7074834f630ab1b464c357'),
    (4032, 47, 10, 32, 'Come on, spill the beans — what happened?', 'He always spills the beans — never tell him secrets.', 'b5548441b30fb1924df78f0e169464452e77608d04967371b0b3d7f9eed25ca1', '421eb2db8acb90ea1c77d57db07f326d3c67254244ad763e1b5991523fddebe6'),
    (4033, 47, 11, 33, 'Have you got Friday''s shift covered yet?', 'We''ve got the music covered, so just bring snacks.', 'b4de2e3ee72bb675c34c1e0647b0bd54af08d41ecb1f0a23f3ef492960276023', '603bbd9bc7ec312f4a8777239aa2946c522e3ebc75ab1cd1967b061669ede9eb'),
    (4034, 50, 1, 34, 'That''s sad. You loved that bike.', 'That''s sad. You waited for months.', '1dcc2e862bf63e0696636232eb9f59db5b42e4e0ddb5fd7dedbc9099c3a62f87', '6a68a6ee6a33e3d96ba2bb3f01b78a90d5e6480ac10fcdc4687a43ad12baee3c'),
    (4035, 50, 2, 35, 'I did, too. Now I feel sleepy.', 'I did, too. My alarm was off.', 'd8f04ec3175a50e75a0bba98bc3538af88b14290a49453c68cc9ec0b808125ff', '31d993325098aab7727a09e895f637466080249024fe186a47947f22530a7496'),
    (4036, 50, 3, 36, 'Yes. It helped me every week.', 'It helped me on bad days.', '10be708aaa0a9a1fd3122d78917cd343ac1fcfafe34818b12ef336fabdd50d31', '4bbc1709ff8e47a687feb2ae54aaf6d8d4fe0406c883d012f47a0dfc4a628d76'),
    (4037, 50, 4, 37, 'Let''s go to my house.', 'Let''s go to the new bakery.', '5931dad0738e7a9658d98e11cafe0f7c44b70a20616687b48f9fa182ae8ca48f', '3ff89005bf1d0ef0dbff14f6bdd2301ea84008e96aa2c9c341eedb50453e327a'),
    (4038, 50, 5, 38, 'It''ll be okay. You''ve practiced this more than anyone.', 'It''ll be okay. You two always make up by dinner.', '74baa9fb4ba6b2cc54f233fcc5c796980f99b2f08a54327a3f445dd82d138be6', 'b6aed7e98a57e0504a475feb2a21d35cddec5587a39710bd38dd0e839622e947'),
    (4039, 50, 6, 39, 'You did your best in the rain all day.', 'You did your best until your knee hurt.', '97cd02a09b9daf8185c8a107b6834fc0c6315ddb112ab118d16dd989b23edf22', 'ba9cf842e55a423c5bc9db46dc6a1d4c04d3454649ce8bfe4a413b6cc0deed58'),
    (4040, 50, 7, 40, 'The same thing happened to me during my first week.', 'The same thing happened to me, so I stopped worrying about it.', '851ad0edd82f8e7e8a495d92faed7b3341f55df0f23c60ea36e5c025c9b300e2', '010ece05ea4a0585c3abda11f5ba94bfe61bc87c8884575ec154c2d86a9b6a57'),
    (4041, 50, 8, 41, 'Let''s do something fun here instead. I have a plan.', 'Let''s do something fun tonight. I''ll call the others.', '4527f86f896d7f73952530820b24557b03b15b007b471b9edd9b8bf423f4c395', 'f99723f3849f0396714375e002e272b8fda46f450bd174adea94c3561d31460a'),
    (4042, 50, 9, 42, 'She brushes off compliments every single time.', 'Don''t brush off what the doctor told you.', 'c6cd86d95fc7bfeccf65192d3c2f4df4830b837dd23238023a8a8a7123f3738a', '4889edc72f66f8626e793b24b5aa067e3add2d4eab41bd39177416e04c203ec2'),
    (4043, 50, 10, 43, 'There''s no point beating yourself up now.', 'He beats himself up over every little thing.', 'abe6eda7b6cf7ceac904eeb3d109e7918d8efc17e9ffea57d51851e8e2a3b1b9', '429db8f28371df3e1a2edf0077e219c555e612bdcd114b3282387082988cf343'),
    (4044, 50, 11, 44, 'This tea is perfect for unwinding before bed.', 'You should unwind a little before the interview.', 'cc502fff50c5730bac84342ecbb71b60653d15d6193ba0427ac9b9984d6a47be', '358be96cd6e5db2ce518a17f8c776ea02c86939b98d79687f6ef9726ed87abda'),
    (4045, 54, 1, 45, 'I will go to my dream place.', 'Spain is my dream place.', '8944e390a5444ba8ad069d98c5335d4e8cad744bcec4fcf910256381cca36c3a', '0731f0f720625c0204b548c356b41aff0cec00f4835ddfcfca03003541a4ba11'),
    (4046, 54, 2, 46, 'Sure. I have twenty dollars.', 'I have ten dollars, so no.', '1e47440fc4c8a21ab9d81293fab6dc7da8311dc7d7979f62f9336498382a9e4b', 'e478d9e2149b98a731033d6aa59cfbc9388a88bb40ae47aab25dc088c510f5e3'),
    (4047, 54, 3, 47, 'Yes, but I need it for three days.', 'It rained for three days.', 'db4d1525ef7dfa820c14c5d0ad94aff28e3cdab6128cac51360523a646d70c2a', 'f002e5c4551d71fda971a660bc7ae89fd82238c9c40a3e85c901c7ad9b1de5da'),
    (4048, 54, 4, 48, 'I found a cheap hotel online.', 'I always pick a cheap hotel.', 'b4b1db5243ccfed7d51c49797d91e8f7e3a67b4adac4219aec431573f8793d33', 'a99b2d52aeba259ee1cf54ede77990441e4ae3f784cc1549ba9a375ee03389d3'),
    (4049, 54, 5, 49, 'I always pick a place I''ve never been before.', 'That''s why I want a place I''ve never been.', '0cef7bcd10576754744d9eb6a90c606fffeff917eb65407f3a2d91554fab3554', '386114d6d642d6e42df104cf3b434273afc820f18fa0c3cd876ece3cc7a75200'),
    (4050, 54, 6, 50, 'I spend about twenty minutes getting ready.', 'Not really. I spend about ten dollars a week.', 'c053d480cef8d5e8b849e77fa4a47797d5a760c0b91effec6e3a1ed090daae1e', '116055f3d080b4e874f66647a53bdda46590f41e72fb7b21af3352d68c2123e6'),
    (4051, 54, 7, 51, 'The bus. I''m trying to keep it cheap this month.', 'Let''s keep it cheap, or we''ll run out of money.', '1ba2b173f46f2b4b3894da30d4e953b74885949a0daaa66ff2811f7d39807894', '677e82ac26d0ca47081646fb339a0a986dd1cf14e8b3a7f5c391585502c5159f'),
    (4052, 54, 8, 52, 'Yes, because I didn''t book a room yet.', 'I book a room as soon as I pick the dates.', 'e898900271bf1c5bfb0ecd02c2afa193a74156bdd6d0729973332d39fba5dccc', '8107be65c6c288e21d6194025e0d193e16a8356b3916a853222da56d543bf8ed'),
    (4053, 54, 9, 53, 'The four of us split the cost evenly.', 'Splitting the cost makes it way cheaper.', 'fae98fdf3e1f49ea2506d1e79e6c0e1d399b00cd2fc5a62a657f89f87730f133', 'b1dc2de74ce199071aa33dc46e00e2781d8fab38af0bbe98d8d61204dc9ea3a4'),
    (4054, 54, 10, 54, 'I''m so torn — both dates work for me.', 'He was torn between staying and leaving.', '3e1023aa3604f97af2cc9dce4ce5544d1345a39c01e76c43709217e5cbed3c2b', 'e3b2daabd406b6db50edcbb379c4f9fc54d299229a19181bb6f0282f39d40617'),
    (4055, 54, 11, 55, 'The menu is surprisingly budget-friendly.', 'Any budget-friendly ideas for the weekend?', '71a1db8641e6bdaa9d5fdca2f11351558223ca67ff85c8d6716d2e493f1a2f4e', 'c38e580dab5b0cda8c3eff636c9fec9c3d00b08b91abc15695710c431eebe82c'),
    (4056, 64, 1, 56, 'I can see my favorite band there.', 'Yes. I got to see my favorite band.', '153c93c3a600a1bb6dcc0637279aea78a9229f7cabe708a5d88c6120972aa9ee', '38ff85322223c8ed515f707ec9f9fbd566460dc98aa4bb6a2d57c4e605fb1c47'),
    (4057, 64, 2, 57, 'Let''s meet there. I can go then.', 'I can go then, too.', 'a74600356eca5c80fa76e6594e64ffafaafd4fc3ba1105ecf5111f7a6087d5be', 'e46b8ebe10074c68c8d538711cfe6b3b446d117d2c0ffa23d7ea6d8f445e22d1'),
    (4058, 64, 3, 58, 'This time we pay half each.', 'My sister will pay half.', 'a9626d4cf34bc35ceb4417cc28246e434eea8a92fbf95a1a292936b14e1d5fe7', '910fba219b19aecd2144d9181de30a0f692e96bc370acbc8c16a22c539ea6411'),
    (4059, 64, 4, 59, 'A little. We stayed in a tent.', 'I like eating in a tent.', 'e284aac67927c1a86244fb4c207f3752827daef0fa6c368d2781bb88d0f349d3', '24bc32e106c3f15d32c61c1237b56ce6df6ad7372bfae7a36d5922c5c71e0fe9'),
    (4060, 64, 5, 60, 'Well, I''m definitely going, so put my name down.', 'I''m definitely going, even if I stand the whole game.', '9f2c6d6c47ba71851cefb7f69697bfa833d3e2b1a101b6c66f6ce7be4b2e6412', '602ff93eeef4980d2100eee5138f85cffc0b2c26486748143c0b1853acdd47ad'),
    (4061, 64, 6, 61, 'Either weekend works for everyone on my team.', 'Either weekend works, so let them choose the date.', 'e3b3c7ff5930749b68f774dae2d8ac7ed6fd0b47843115fc237ae68de616b2d3', '35216fc188063173736580daa70f8edcd3843809dc78e9a544e4c9588a3799cc'),
    (4062, 64, 7, 62, 'No way. I''ll send you the money this week.', 'Got it. I''ll send you the money right now.', '72b3b1339748380df86994a4a4798d8154143d6ec80d1c20abba98401f83bb60', '3dede13ed76d2f665809c997d4c513bc97c8d09bdbf6fa057207ff6b785ed489'),
    (4063, 64, 8, 63, 'I''d rather share a room. It''s cheaper and more fun.', 'I used to share a room with two roommates.', '2655baa5b262aeae6cd889366db788ce0eb10f5a89916fe5adbacf61b10026d3', 'cc3c8b2d14fe320e3345f9660dddeba9ae9c1829252c9a24b127c0e28ae2e5a3'),
