    (4185, 48, 10, 185, 'Take a jacket just in case it gets cold.', 'I left early just in case there was traffic.', '331b63d7c2fa7cfa14460bdd18144ab1b3130fe7b107d72c35dc7ba67b5b6bd5', 'c0375a6d16e8b986702bd47a1aab1aaa04d9b84d3d867abbc7b362113fbd72a3'),
    (4186, 48, 11, 186, 'It''s too hot — let''s exercise indoors today.', 'I prefer staying indoors in winter.', '7dc7007f2b9504f239f427d0abbe6b12da77e991d381339934d474b1e58a7a1e', 'a8b7e9973a1ceb549edfa07d9c10425bef9fd0ae9411a4fbefdf3bd2bd383f79'),
