-- 대표 이미지 ID:시나리오:표현순서:SQL행:WebP SHA-256 매핑 SHA-256: 7834958aee53b664cb99555633f8db9feda37b3433e69b7686af07e2f3437aed.
CREATE TEMP TABLE lan391_representative_image_map (
    expression_id BIGINT PRIMARY KEY,
    scenario_id BIGINT NOT NULL,
    expression_display_order INTEGER NOT NULL,
    sql_values_row INTEGER NOT NULL UNIQUE,
    sentence_en TEXT NOT NULL,
    sentence_ko TEXT NOT NULL,
    question_en TEXT NOT NULL,
    question_ko TEXT NOT NULL,
    image_sha256 CHAR(64) NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO lan391_representative_image_map (
    expression_id, scenario_id, expression_display_order, sql_values_row,
    sentence_en, sentence_ko, question_en, question_ko, image_sha256
) VALUES
    (4001, 44, 1, 1, 'I play tennis after school.', '나 방과 후에 테니스 쳐.', 'Hi! What sport do you like?', '안녕! 무슨 운동 좋아해?', '56a4f3cb12fa54d02e7e647d7f92119bee8a13eddaf70e38eaedf0a5b0e78542'),
    (4002, 44, 2, 2, 'Do I need a racket?', '나 라켓 필요해?', 'We are the tennis club. Do you have a question?', '우리는 테니스 동아리야. 궁금한 거 있어?', 'c500e6bcc039fedb2dd4cc5ad15131f77ddcff53a19d6e3b76d0ab48d592c31c'),
    (4003, 44, 3, 3, 'That sounds fun! I want to go.', '재미있겠다! 나 가고 싶어.', 'We have a party this Friday. Do you want to come?', '이번 주 금요일에 파티가 있어. 올래?', 'e71f253affe56dfc956d659c10f64801f685354155fcf2f4bcf1cb508a8ad01f'),
    (4004, 44, 4, 4, 'I''ll be there on Friday.', '나 금요일에 갈게.', 'Do you want to come?', '올래?', '2a80f20d38eff54c50ad0ba67afe280ee8ce42b3a9506de809fdc6a7319e17f7'),
    (4005, 44, 5, 5, 'I''m looking for a club that meets after class.', '수업 끝나고 모이는 동아리를 찾고 있어.', 'Are you planning to join a club this semester? What kind of clubs do you enjoy?', '이번 학기에 동아리 들어갈 생각 있어? 어떤 종류의 동아리를 좋아해?', '7d1f43b00fabd6435ec4d813480be507dfa1273cbf337482db2fe3893ce09dbf'),
    (4006, 44, 6, 6, 'I''m a total beginner, but I really want to learn.', '나 완전 초보인데, 진짜 배우고 싶어.', 'We''re the tennis club. Is there anything you want to ask?', '우리는 테니스 동아리야. 궁금한 거 있어?', '3f2e9c8b9e86ee0c97e397bdaa070635b5331db37890e8d6d923d2d5c9414f6a'),
    (4007, 44, 7, 7, 'What should I bring on the first day?', '첫날에는 뭘 가져가면 돼?', 'We''re the tennis club. We play every Friday afternoon, and it costs five dollars a month. Is there anything you want to ask?', '우리는 테니스 동아리야. 매주 금요일 오후에 치고, 한 달에 5달러야. 궁금한 거 있어?', 'bcd42d937b55a3f98b8a06a8ad79584342f7881e118d204934edaafbe8afc8fe'),
    (4008, 44, 8, 8, 'I''ve never been to one, but I''ll give it a try.', '그런 데 가본 적 없는데, 한번 가볼게.', 'We''re having a welcome party for new members this Friday. Would you like to join us?', '이번 주 금요일에 신입 환영회를 해. 우리랑 같이 갈래?', '61f118066dcaf5e69abea5b5590db993c59c462620565ab9b095ff77265fa6fd'),
    (4009, 44, 9, 9, 'Can I try one session first? What do you say?', '한 번만 체험해봐도 돼? 어때?', 'We''re the tennis club! Total beginners are welcome too. Anything you want to ask?', '우리는 테니스 동아리야! 완전 초보도 환영이야. 궁금한 거 있어?', '7d405186e82df2b466c3f737c4f605a9f7a71ef4829cb4cae67e4a77206dc0fc'),
    (4010, 44, 10, 10, 'I''ve always wanted to be part of a sports club.', '운동 동아리의 일원이 되는 게 늘 로망이었어.', 'Hey! What kind of clubs are you into?', '안녕! 어떤 쪽 동아리에 관심 있어?', '84b8073a00cc66a5f34982faae92126ba4b21143674b399a1dc8963f72ed19bc'),
    (4011, 44, 11, 11, 'Of course I''m going — I wouldn''t miss it!', '당연히 가지 — 그걸 어떻게 놓쳐!', 'We''re having a welcome party for new members this Friday — wanna come?', '이번 주 금요일에 신입 환영회 하는데 — 올래?', '51b52287c7d7562484ef2d800fd0b04003a07348e4f52170f8f0a1b99576f0cf'),
    (4012, 41, 1, 12, 'You will like bulgogi.', '너 불고기 좋아할 거야.', 'There are so many foods! Which one is good?', '음식이 정말 많아! 어떤 게 맛있어?', '0af69123d9eca1b589ab7844095bf25c8bd1a830c396bc318ea40ef5f0e230f3'),
    (4013, 41, 2, 13, 'Let''s try the fried chicken.', '우리 치킨 먹어보자.', 'Which one is good?', '어떤 게 맛있어?', '1341b932bab53ebf678f54364b5c3e1f99a6ef6fb251a675fc720c07a76bb4fa'),
    (4014, 41, 3, 14, 'This soup is a little spicy.', '이 국은 조금 매워.', 'I can''t eat spicy food. Is this one spicy?', '나 매운 거 못 먹어. 이건 매워?', 'be925a5e1a3e530bd8bc3691d0d49bd06ccbf7ba7a368adbb5097e4197d19627'),
    (4015, 41, 4, 15, 'Mix the rice and vegetables together.', '밥이랑 채소를 섞어.', 'How do I eat this? Show me!', '이거 어떻게 먹어? 알려줘!', '5d7acd4827b8bfbb51905443410214659aa6ec0d94650ee84ae92fbb37b3bf50'),
    (4016, 41, 5, 16, 'I''d pick the beef soup, because this place is known for it.', '난 소고기국 고를래. 여기가 그걸로 유명하거든.', 'There are so many dishes here. Which one would you pick for me, and why?', '여기 메뉴가 정말 많다. 나한테는 어떤 걸 골라줄래? 왜 그거야?', '06dde5fead18be6cd2b21e59bbe7a1a71930a75f31fac2e67db45f4e9c6a08f1'),
    (4017, 41, 6, 17, 'Don''t worry, it''s less spicy than the red stew.', '걱정 마, 저 빨간 찌개보다는 덜 매워.', 'I''m not good with spicy food. Is this dish hot?', '나 매운 걸 잘 못 먹어. 이 요리 많이 매워?', 'e14735123f49ce33b036ac5ebb4987e7a150695f4fe53e324af5a783b0202cc9'),
    (4018, 41, 7, 18, 'Eat it a little at a time, and you''ll be fine.', '조금씩 먹으면 괜찮을 거야.', 'Is this dish hot?', '이 요리 많이 매워?', 'a9010f689f554f65663303a09f56702abb5988897739603109b086d33d9e0126'),
    (4019, 41, 8, 19, 'Wrap the meat in a lettuce leaf and eat it whole.', '고기를 상추에 싸서 한입에 먹어.', 'How am I supposed to eat this? Do I mix everything, or eat each thing on its own?', '이건 어떻게 먹는 거야? 다 섞어서 먹어, 아니면 따로따로 먹어?', '3a8bf8830c18e08ce2cca459e7d9e6c37ecd94b805690e8af8a52ecd3dbbb0ea'),
    (4020, 41, 9, 20, 'Go with the bulgogi — it''s always a crowd-pleaser.', '불고기로 가자 — 그건 누구나 좋아하거든.', 'There are so many options! What''s the best thing here? You pick for me.', '메뉴가 너무 많아! 여기서 뭐가 제일 맛있어? 네가 골라줘.', '6525995fb77c03f1249cb4a39d3333a89d853678c7e6dd01eff76a5794971a76'),
    (4021, 41, 10, 21, 'Everything''s ready — let''s dig in!', '다 나왔네 — 자, 먹자!', 'Oh, the food''s all here! Can we start eating?', '오, 음식 다 나왔다! 이제 먹어도 돼?', '294dbdc869e51fcf900ee5f83d3fce7ef0581a6128d1b979473f9df873f9105b'),
    (4022, 41, 11, 22, 'Wash it down with some cool sikhye.', '시원한 식혜로 넘겨봐.', 'I''m not great with spicy food… is this one really hot?', '나 매운 거 잘 못 먹는데… 이거 많이 매워?', '2cb6c506c8be7e6fe6a72c27e78e864de79991286d0abc5c519cd5e40ec16469'),
    (4023, 47, 1, 23, 'I like that idea. Let''s do it!', '그 생각 좋아. 하자!', 'Next week is Marco''s birthday. Do you want a party?', '다음 주가 Marco 생일이야. 파티 해줄래?', '9612aa2b83a12d09b019501123c4509ddbf63d490c416d8ed772b2d763247869'),
    (4024, 47, 2, 24, 'Yes! Let''s plan a surprise for him.', '좋아! 걔한테 깜짝 선물로 해주자.', 'Do you want a party?', '파티 해줄래?', '1441877b4a638a075fcdffdb26abdba90fdcb165872c10b396231b1d168b7630'),
    (4025, 47, 3, 25, 'I can buy the cake.', '케이크는 내가 살게.', 'We need a cake and balloons. Which one do you want?', '케이크랑 풍선이 필요해. 넌 어떤 걸 맡을래?', '99eec6974985253ffaa0157ee3b3eae5f9c95c632b5c93a6e906370e492c38c6'),
    (4026, 47, 4, 26, 'I will bring him. It''s a secret.', '내가 데려올게. 걔한텐 비밀이야.', 'Marco can''t know! How do we bring him to the room?', 'Marco가 알면 안 돼! 어떻게 방으로 데려오지?', '80147bfbdcc4f831b11eac300a77f5c4b4a3620c19c62299ac5221503d8ecc56'),
    (4027, 47, 5, 27, 'That sounds like fun. He never expects a party.', '재밌겠다. 걔는 파티 같은 건 생각도 못 할걸.', 'Marco''s birthday is next week. I want to plan a surprise party for him. What do you think?', '다음 주가 Marco 생일이야. 깜짝 파티를 준비하고 싶은데, 어떻게 생각해?', '254f1e4a93a32675a82947fe182618d2460aed1b3508010c7a8d5808eba293b2'),
    (4028, 47, 6, 28, 'I''ll handle the decorations, so you can focus on the cake.', '장식은 내가 맡을게, 넌 케이크만 신경 써.', 'We need a cake, some decorations, and someone to invite his friends. Which part can you take?', '케이크, 장식, 친구 초대가 필요해. 넌 어떤 걸 맡을 수 있어?', 'a5b83cf653317fe3d1a0d643097f7598b1c8a1a1ae28e3656e2d9830de351d19'),
    (4029, 47, 7, 29, 'I''ll make an excuse about a broken light and bring him up.', '전등이 고장 났다고 핑계 대고 데려올게.', 'How can we get Marco to the room without making him suspicious? Do you have any ideas?', 'Marco가 눈치채지 않게 어떻게 방으로 데려올까? 좋은 생각 있어?', 'd9672211d3129d2242264396eb9e9e5f18a80e53a8488a6131187278bb33e87a'),
    (4030, 47, 8, 30, 'Let''s pretend to forget his birthday until the party.', '파티 전까지는 걔 생일 잊은 척하자.', 'How can we get Marco to the room without making him suspicious?', 'Marco가 눈치채지 않게 어떻게 방으로 데려올까?', 'c3a957220239118f9ae7506ad4ca30979c07856cb6851ee3fd8696ca279c40ac'),
    (4031, 47, 9, 31, 'I''ll walk him over, and you two just act natural.', '내가 데려올 테니까, 너희 둘은 아무렇지 않은 척만 해.', 'Okay, last thing — how do we get Marco to the room without him noticing anything?', '좋아, 마지막으로 — Marco가 눈치 못 채게 어떻게 방으로 데려오지?', 'bbd51f039a78317d37b0035ac50831edeb87d75618e2a047f43ea3fc68f804f0'),
    (4032, 47, 10, 32, 'No, and don''t spill the beans before Friday!', '아니, 그러니까 금요일 전에 비밀 흘리지 마!', 'Wait, does Marco know anything about this?', '잠깐, Marco가 이거 뭔가 알고 있어?', 'eb22bd8956c60ef43d3e629e0aebdac7bc9f4ddfe12fe9833a1ed2682d675244'),
    (4033, 47, 11, 33, 'You take the cake, and I''ve got the decorations covered.', '케이크는 네가 해, 장식은 내가 맡을게.', 'We need a cake, decorations, and someone to invite his friends. Which one do you want to take?', '케이크, 장식, 친구 초대가 필요해. 넌 어떤 거 맡을래?', '0c5aef092a1b79cd892f09eb12e4c23473b7a2a8c8a8c0bf5c6d8106c4cf749d'),
    (4034, 50, 1, 34, 'That''s sad. You studied so hard.', '그거 속상하겠다. 너 진짜 열심히 했잖아.', 'I did very badly on my test. I feel so sad.', '나 시험을 정말 못 봤어. 너무 속상해.', 'dc0077dfca1192ef8018f0711d7d23089b061f176384d9819f2487f42d55d817'),
    (4035, 50, 2, 35, 'I did, too. Last year was hard.', '나도 그랬어. 작년에 정말 힘들었어.', 'Did you ever do badly, too?', '너도 그런 적 있어?', '2608770303ae7b7641513a976de5f9187a54ade2f656b1f3af43f3ac74226e82'),
    (4036, 50, 3, 36, 'I talked to my mom. It helped me.', '엄마한테 얘기했어. 그게 도움이 됐어.', 'Did you ever do badly, too? Tell me more.', '너도 그런 적 있어? 더 얘기해 줘.', '98c3ace05905ca0369e621f393be488583ef0618999dc637a837fed868253d61'),
    (4037, 50, 4, 37, 'Let''s go to the park today.', '오늘 공원에 가자.', 'I want to feel happy again. What can we do today?', '다시 기분이 좋아지고 싶어. 우리 오늘 뭐 할까?', 'e01624f53a309942dcb456e474d11f64de7c8d4a1d85b8e6ddc7248fac8f5f45'),
    (4038, 50, 5, 38, 'It''ll be okay. One midterm won''t decide everything.', '괜찮아질 거야. 중간고사 하나가 다 정하는 건 아니야.', 'I did terribly on my midterm. Almost nothing I studied was on the test.', '나 중간고사 정말 못 봤어. 공부한 게 시험에 거의 안 나왔어.', '2a6f2feaec0460ef21c3afd71fc396b804a033fda5b20949d1208ded613bf73c'),
    (4039, 50, 6, 39, 'You did your best, and that''s what counts.', '넌 최선을 다했어. 그게 중요한 거야.', 'I did terribly on my midterm.', '나 중간고사 정말 못 봤어.', '96df5fdf415356267fa78fa1a3e6681609ded0070635b8edaa1e7c84a28cf63c'),
    (4040, 50, 7, 40, 'The same thing happened to me last year. I just started over.', '나도 작년에 똑같은 일이 있었어. 그냥 처음부터 다시 했어.', 'Have you ever done badly on an important test? How did you deal with it?', '너도 중요한 시험을 망쳐본 적 있어? 그때 어떻게 했어?', '3022c030eb47260955a413d6116065d8b420c1e47ce9d2ed9fc21232205f46ea'),
    (4041, 50, 8, 41, 'Let''s do something fun this afternoon and forget the test.', '오늘 오후엔 재미있는 거 하고 시험은 잊자.', 'I want to forget about it for a while. What should we do together this afternoon?', '잠깐 잊어버리고 싶어. 오늘 오후에 우리 같이 뭐 할까?', '989b7ade0baf8666f4ba5b1c63c8a6f9013e12f7bf7dc6f43c9a17ea849859bb'),
    (4042, 50, 9, 42, 'I tried to brush it off and focus on the next one.', '난 그냥 털어버리고 다음 시험에 집중하려고 했어.', 'Have you ever bombed a test? What did you do to get over it?', '너도 시험 망쳐본 적 있어? 그럴 땐 어떻게 극복했어?', '59a5bf12bbf3217b0408b18ed0e9ec112525796d28930c17c065e10689aea8bd'),
    (4043, 50, 10, 43, 'Don''t beat yourself up over one test.', '시험 하나 가지고 자책하지 마.', 'I totally bombed my midterm…', '나 중간고사 완전 망쳤어…', '064dcbad3d16ceab2a0e8b12846cc1049310bb258c5ceec8acb5422fda2e973c'),
    (4044, 50, 11, 44, 'How about a movie and pizza? That always helps me unwind.', '영화 보면서 피자 먹는 거 어때? 그러면 난 늘 긴장이 풀리더라.', 'Ugh, I need to clear my head. What should we do to cheer me up?', '아, 기분 전환이 필요해. 우리 뭐 하면서 기분 풀까?', '68dd4d2399999cb79cf7615c07202389011264e33f9871822fa38dcc44a65f86'),
    (4045, 54, 1, 45, 'Paris is my dream place.', '파리가 내가 꼭 가보고 싶은 곳이야.', 'Let''s travel this vacation! Where do you want to go?', '방학에 여행 가자! 어디에 가고 싶어?', '55c929df19740128e21f08c58d821fe9b54fe1ebf96267908aecf518e75dd9fe'),
    (4046, 54, 2, 46, 'I have three hundred dollars for the trip.', '나 여행에 쓸 돈 300달러 있어.', 'I want to save money. How much can we use?', '나 돈을 아끼고 싶어. 우리 얼마나 쓸 수 있을까?', '517590eaa04696bd569448d637ae72c88d9e1775c7919b95db602b4ada366a9e'),
    (4047, 54, 3, 47, 'Let''s go for three days.', '사흘만 가자.', 'How many days should we go?', '우리 며칠 갈까?', '5355e1b7760344cdc222e572b1cd716fc30fc7c968ce75aff2567a23b38fd94f'),
    (4048, 54, 4, 48, 'Let''s find a cheap hotel near the beach.', '바닷가 근처에 싼 호텔 찾아보자.', 'We need a room too.', '방도 잡아야 해.', 'e2c8ff04403cd7fa19dec896c18812bc1a3b29d56e1a7040bfcebb1dccb80391'),
    (4049, 54, 5, 49, 'I want to go somewhere new, a place I''ve never been.', '새로운 데 가고 싶어. 한 번도 안 가본 곳으로.', 'Let''s travel together this vacation! Where would you like to go, and why there?', '이번 방학에 같이 여행 가자! 어디에 가고 싶어? 왜 그곳이야?', 'cf29c6bb0cf9247b09e7fc20569312e060fd579fb92c3bc1ebef4ba0e3a77670'),
    (4050, 54, 6, 50, 'Let''s spend about six hundred dollars each, including the flights.', '비행기값까지 해서 한 사람당 600달러 정도 쓰자.', 'How much money should we plan for? I''m trying not to use too much this time.', '돈은 얼마 정도로 잡을까? 나는 이번엔 너무 많이 쓰지 않으려고 해.', '22f8479b583a4ab84be54a18c727e04ba1e08a9f39dbe9afce67aacdc555455f'),
    (4051, 54, 7, 51, 'Same here. Let''s keep it cheap and cook some meals.', '나도 그래. 싸게 가자. 밥도 몇 끼는 해 먹고.', 'I''m trying not to use too much this time.', '나는 이번엔 너무 많이 쓰지 않으려고 해.', '42645516934091dcd889128f68efb2cf3acc23522c1b3a08b146dedf4071a3a5'),
    (4052, 54, 8, 52, 'Three nights sounds good. I''ll book a room at a hostel.', '3박이면 좋을 것 같아. 내가 호스텔에 방 예약할게.', 'How many days should we stay? And would a hostel be okay for you?', '며칠 정도 머물까? 그리고 숙소는 호스텔도 괜찮아?', '66c3d96da642e5a962dd5678fe9a114fa6d43e63b4de6229c87cd01b1c8ac324'),
    (4053, 54, 9, 53, 'Let''s split the cost between us.', '우리 둘이 비용을 나눠 내자.', 'How much are you thinking for the budget? I kind of need to save this time.', '예산은 얼마 정도 생각해? 나 이번엔 좀 아껴야 하거든.', '29aad5e511333f1e94fb50ad5b4846b54693af6f4df6849b02d190318670dd6e'),
    (4054, 54, 10, 54, 'Honestly, I''m torn between the two.', '솔직히 둘 중에 못 정하겠어.', 'Let''s go on a trip together this break! So, the beach or the mountains — where do you wanna go?', '방학에 같이 여행 가자! 바다랑 산 중에 — 어디 가고 싶어?', '31e70aedb230706755489d1cd6b105ce91f06b06d8dbfc5682cba763cbdd8e34'),
    (4055, 54, 11, 55, 'I found a budget-friendly hostel downtown.', '시내에 가성비 좋은 호스텔 찾았어.', 'How many days should we go for? And is a hostel okay with you?', '며칠 다녀올까? 숙소는 호스텔도 괜찮아?', '291387a03d3fdfd690d43d19227fc254618a1c8cf2584e40a0a669ea8e6c3b5c'),
    (4056, 64, 1, 56, 'Yes! I want to see my favorite band.', '좋아! 내가 제일 좋아하는 밴드 보고 싶어.', 'Coachella tickets are on sale! Do you want to go with me?', '코첼라 티켓 예매 시작했대! 나랑 같이 갈래?', 'ee29947fbf72cf1f743fd64893310fa1000b657ccf6a6f7f23c7325d3f0c16b6'),
    (4057, 64, 2, 57, 'Yes, I can go then.', '응, 나 그때 갈 수 있어.', 'Is the weekend in two weeks okay?', '2주 뒤 주말은 괜찮아?', 'be8fc266ab227842c4d701ebb7715ba5f8bf18868ded2a2118763d5cc9b1f0d2'),
    (4058, 64, 3, 58, 'I can pay half for the tickets.', '티켓값 반은 내가 낼게.', 'Tickets are 400 dollars.', '티켓은 400달러야.', 'af214be52e7005505985068143059a146a6e7646411e687dd6ed79a421a90b9f'),
    (4059, 64, 4, 59, 'Let''s sleep in a tent.', '텐트에서 자자.', 'Do you want to camp or stay in a hotel?', '캠핑할래, 호텔에서 잘래?', 'fbba8371dc9e16a5f01ccf5a1b3818a358127107669939d7b1926e99391a078d'),
    (4060, 64, 5, 60, 'I''m definitely going. I''ve waited for this lineup all year.', '나 무조건 갈 거야. 이 라인업 일 년 내내 기다렸어.', 'Coachella tickets just went on sale! Do you want to go together?', '코첼라 티켓 예매 열렸대! 우리 같이 갈래?', 'a4d32000d7dbdbe1e873aa1d33d5d5ee2a6fc041a9ee95b37c813b820fd403fd'),
    (4061, 64, 6, 61, 'Either weekend works for me, so pick the one you want.', '나는 어느 주말이든 괜찮으니까 네가 원하는 쪽으로 골라.', 'Which weekend works better for you, One or Two?', 'Weekend 1이랑 2 중에 어느 쪽이 더 괜찮아?', '54c5f2542cc9c3da991dda614646d9de742e1a39dc63442f75daa004495af674'),
    (4062, 64, 7, 62, 'You buy both tickets, and I''ll send you the money tonight.', '네가 티켓 두 장 사면 내가 오늘 밤에 돈 보낼게.', 'How should we pay for them?', '티켓값은 어떻게 낼까?', '931078ad5fe3863f476652cadaa61fe8ec55d71027245023665a96878807082a'),
    (4063, 64, 8, 63, 'Let''s get a hotel and share a room to save money.', '호텔 잡아서 방 같이 쓰자. 그럼 돈도 아끼고.', 'For a place to stay, would you rather camp or find a hotel nearby?', '숙소는 캠핑이 좋아, 아니면 근처 호텔을 알아볼까?', '7dc31d77cab48c30cf898b52e9fc496f086dc4ef9e8d46938c9ec9d140771781'),
    (4064, 64, 9, 64, 'Are you kidding? I''m dying to go!', '장난해? 가고 싶어 죽겠어!', 'Coachella tickets just went on sale!! We have to go together!', '코첼라 티켓 예매 열렸대!! 우리 무조건 같이 가자!', '632a0cf6b2031af77d387a87c0ce5a48828c1dcdc61f3cd719438a6783a08d34'),
    (4065, 64, 10, 65, 'It''s tight, but I''ll make it work.', '빠듯하긴 한데, 어떻게든 되게 해볼게.', 'Which weekend works for you, One or Two?', 'Weekend 1이랑 2 중에 언제 돼?', '54e129c69fe54421ae613af00bab0ae0e0d502bd842b83c3d8242500409f649e'),
    (4066, 64, 11, 66, 'If we split them, the tickets won''t break the bank.', '우리가 나눠 내면 티켓값이 그렇게 부담되진 않을 거야.', 'Which weekend works for you, One or Two? Let''s split the tickets when we book.', 'Weekend 1이랑 2 중에 언제 돼? 예매할 때 티켓값은 나눠 내자.', '4805a6168424b57de6fa4b4de50548577f107bd513e6d47279147e4327c761ec'),
    (4067, 58, 1, 67, 'Yes, I lent you my math book.', '응, 내가 너한테 내 수학책 빌려줬어.', 'Hmm, did I borrow a book from you?', '음, 내가 너한테 책을 빌렸었나?', 'ae610177c452cb7f9a8157596ba8821775deeb08f278ecc6d92157bd2a5d5d1b'),
    (4068, 58, 2, 68, 'Yes, you borrowed it a month ago.', '응, 너 한 달 전에 빌려 갔어.', 'Hmm, did I borrow a book from you?', '음, 내가 너한테 책을 빌렸었나?', '7f49d57a5921669a0a9e11208a030bb6b957945ac74fe0526e6cbf1fa3f414c9'),
    (4069, 58, 3, 69, 'Sorry, I need it now.', '미안, 나 지금 그거 필요해.', 'Oh no, I forgot! Can you wait a few days?', '헐, 깜빡했어! 며칠만 기다려 줄 수 있어?', '99cf9579eec5ca19a8bfc1a10e4060ca0110e9aeb7e11886070d6f8259ac1313'),
    (4070, 58, 4, 70, 'Please bring it before my test.', '시험 전에 갖다줘.', 'I can bring it tomorrow. When do you need it?', '내일 갖다줄 수 있어. 언제 필요해?', '5318b7982fff4ad6655f8bfc83dd02d0c6d30eab0f81a50362943c6d1adae795'),
    (4071, 58, 5, 71, 'It''s the book I lent you last month.', '지난달에 내가 빌려준 그 책 말이야.', 'Wait, did I borrow something from you? Which book was it?', '어? 내가 너한테 뭐 빌렸었나? 어떤 책이었어?', '0369ac7786a327bd7fea093370f2cc74c1bc58e43d507a5c386e54097954d2c7'),
    (4072, 58, 6, 72, 'I can''t wait. I have an exam on Thursday.', '못 기다려. 나 목요일에 시험 있어.', 'I''m really sorry, I completely forgot! But it''s not in my room right now. Can it wait a few days?', '진짜 미안해, 완전 잊고 있었어! 근데 지금 방에 없어. 며칠 뒤에 줘도 괜찮아?', '35b90d61719c962797b7cd90ac69553208b52dbfb36477e307e8341fcd618e7c'),
    (4073, 58, 7, 73, 'Could you look for it today, not next week?', '다음 주 말고 오늘 좀 찾아봐 주면 안 될까?', 'I''m really sorry, I completely forgot! But it''s not in my room right now. Can it wait a few days?', '진짜 미안해, 완전 잊고 있었어! 근데 지금 방에 없어. 며칠 뒤에 줘도 괜찮아?', '8f56445ce2d41f6969a27a7588661d0e0b3b19ba238841dc90cd4f211f84429c'),
    (4074, 58, 8, 74, 'Coffee is nice, but I want the book by tomorrow morning.', '커피는 좋은데, 책은 내일 아침까지 받고 싶어.', 'When do you need it by? I''ll buy you a coffee and bring the book after class tomorrow. Is that okay?', '언제까지 필요해? 미안하니까 커피 사고, 책은 내일 수업 끝나고 갖다줄게. 괜찮아?', '1092fef8f480fe79866748806d8230148ca81604161c8a75421f91f74063c86d'),
    (4075, 58, 9, 75, 'Let me jog your memory — the blue psychology one.', '기억 좀 되살려 줄게 — 그 파란색 심리학 책 있잖아.', 'Wait, did I borrow something from you? Which book was it?', '어? 내가 너한테 뭐 빌렸었나? 어떤 책이더라?', '4c17222679e5bc0a170968f3efcc34f23bb9d45aeb6295ef6ad208543bcd6e84'),
    (4076, 58, 10, 76, 'My final exam is coming up next week.', '다음 주에 기말시험이 다가오거든.', 'I''m so sorry — I completely forgot! I don''t think it''s in my room right now…', '진짜 미안 — 완전 잊고 있었어! 지금 그 책이 방에 없는 것 같은데…', '1657a4461669e95396cb11227c599fc1097381056a3dab8c5e929179c8be91f8'),
    (4077, 58, 11, 77, 'Tomorrow after class is cutting it close, but I can make that work.', '내일 수업 끝나고는 좀 빠듯한데, 그래도 그렇게 하면 될 것 같아.', 'When do you need it by? Tell you what — I''ll bring the book after class tomorrow. Would that work?', '언제까지 필요해? 이렇게 하자 — 책은 내일 수업 끝나고 갖다줄게. 괜찮아?', '99fa0848dae59f591637347f3ef86f7deb24f7bd6bb9d71cb505ec4c150ce5f3'),
    (4078, 65, 1, 78, 'My major is hotel management.', '제 전공은 호텔경영이에요.', 'Hi, can you tell me about yourself?', '안녕하세요, 자기소개 좀 해주시겠어요?', 'da4c34319552d428cb06080f1c6632ad726a5951a817165e8c0a9cd63c16026c'),
    (4079, 65, 2, 79, 'Yes, I worked at a bakery.', '네, 저는 빵집에서 일했어요.', 'Did you work at a cafe before?', '전에 카페에서 일해본 적 있어요?', '052a50166ed902d8b9cb83b9f8267d493189357649e5f11adb1ca276dcd94d4d'),
    (4080, 65, 3, 80, 'I can work three days a week.', '일주일에 사흘 일할 수 있어요.', 'How many days can you work? Tell me your start day.', '며칠 일할 수 있어요? 시작할 날짜도 알려주세요.', '68b9ea36245112ea59dddedf36ea1754c89854d54409e802622a0703dc8e5ba1'),
    (4081, 65, 4, 81, 'I can start on Monday.', '저는 월요일에 시작할 수 있어요.', 'How many days can you work? Tell me your start day.', '며칠 일할 수 있어요? 시작할 날짜도 알려주세요.', 'd70d02bc12cc8e5c46fb5ad0134a8e8e50a0e4ac72ecfbdf79dfa6a3a10b0efc'),
    (4082, 65, 5, 82, 'I study food science at the city university.', '저는 시립대에서 식품영양학을 공부하고 있어요.', 'Hi, you must be here for the interview. Could you tell me a little about yourself?', '안녕하세요, 면접 보러 오신 분이죠? 간단히 본인 소개를 해주시겠어요?', '3e171f5bfe6331a3692a884e2e29535e4110ed7e883c28f3ea350e59c7cafdfb'),
    (4083, 65, 6, 83, 'I have experience in customer service at a busy food court.', '바쁜 푸드코트에서 일해서 서비스직 경험이 있어요.', 'Have you worked in a cafe or in customer service? What would you do when the shop gets really busy?', '카페나 서비스직에서 일해본 적 있어요? 가게가 정말 바빠지면 어떻게 하시겠어요?', '44cd3c924d8775191980740d859d82a3c334e0f5b46a157b0f8aecfcd85027ee'),
    (4084, 65, 7, 84, 'I can work evenings and about twenty hours a week.', '저녁 시간에 일할 수 있고, 주 20시간 정도 가능해요.', 'How many hours a week can you work? The pay starts at twelve dollars an hour, and when could you start?', '일주일에 몇 시간 일할 수 있어요? 시급은 12달러부터인데, 언제부터 일할 수 있어요?', 'cd5d421c6dd22ba72fb6e4c7bc85958a26b5219d3e9c5ccb34045af81c7da77b'),
    (4085, 65, 8, 85, 'Is that per hour? That sounds good to me.', '그게 시간당 금액인가요? 저는 괜찮은 것 같아요.', 'How many hours a week can you work? The pay starts at twelve dollars an hour, and when could you start?', '일주일에 몇 시간 일할 수 있어요? 시급은 12달러부터인데, 언제부터 일할 수 있어요?', '4570907ca0a91529c4ed551df5649b429755ee2399621d159a7f8b0247301c6d'),
    (4086, 65, 9, 86, 'I have solid people skills from volunteering.', '봉사활동으로 다진 대인 능력이 있어요.', 'Have you worked in a cafe or in customer service before?', '카페나 서비스직에서 일해본 경험 있어요?', '79c5e366c17708f7bf7fc8c2269f3dec94329833dadfaae5ca7c0fcb50cedd1a'),
    (4087, 65, 10, 87, 'Right, but I''m a fast learner.', '네, 하지만 저는 빨리 배우는 편이에요.', 'So this would be your first cafe job, then?', '그럼 카페 일은 이번이 처음이신 거네요?', '814d6baca67ea95b75f18e4b3a2bb39941f52eef320f896af9fb2982f3f6b7e4'),
    (4088, 65, 11, 88, 'Yes, I work well under pressure.', '네, 저는 압박 속에서도 일을 잘해요.', 'It gets really hectic during rush hour — do you think you can handle that?', '러시 시간엔 정신없이 바쁜데 — 감당하실 수 있을 것 같으세요?', '89769a119e0904ca56496be58b4dd9bf391a4a5876131db3343aba4b89019186'),
    (4089, 55, 1, 89, 'I have a cough and a runny nose.', '기침이 나고 콧물도 나요.', 'Hello, this is the clinic. What is the problem?', '여보세요, 클리닉입니다. 어디가 안 좋으세요?', '016e616ae504ae4a682a9266945bedc1aa3cd33b10d752a17320d7e126fe55ac'),
    (4090, 55, 2, 90, 'I was sick for two days.', '이틀 동안 아팠어요.', 'How many days, and do you have a fever?', '며칠 됐고, 열도 있으세요?', 'badc015bfc7af938c46aea476622ff9c18a4d4e0c4714736304b4c145ca418d8'),
    (4091, 55, 3, 91, 'I have a little fever too.', '열도 조금 있어요.', 'How many days, and do you have a fever?', '며칠 됐고, 열도 있으세요?', 'a56250a7d50ce665cbcf2dea231d35fdc4e57aeab8475ab56ae409fed4382923'),
    (4092, 55, 4, 92, 'I can come at four today.', '오늘 4시에 갈 수 있어요.', 'We have today or tomorrow. What time is good?', '오늘이나 내일 가능해요. 몇 시가 좋으세요?', '9e831bf00229f0334e0556f0da60ac944b86ce1d5006b30f3b31f7b845bd4e15'),
    (4093, 55, 5, 93, 'I''m not feeling well. I have a headache and chills.', '몸이 좀 안 좋아요. 두통이 있고 오한도 나요.', 'Thank you for calling the clinic. What kind of symptoms are you having?', '네, 클리닉에 전화 주셔서 감사합니다. 어떤 증상이 있으세요?', '28dd81737cfd01f1bd0159360a543719b900a3dcbb3527691f7a391a9a9edd2c'),
    (4094, 55, 6, 94, 'It started Monday, and it seems to get worse at night.', '월요일에 시작했는데, 밤에 더 심해지는 것 같아요.', 'When did it start, and has it changed at all since then?', '언제부터 그러셨어요? 그때랑 비교해서 달라진 게 있나요?', 'fc37762cb1e91ba90ae623b43869b2415b0d222ccd215afd53bc0f5ff353a298'),
    (4095, 55, 7, 95, 'Tomorrow at ten? That works for me.', '내일 10시요? 저는 그 시간 괜찮아요.', 'I have an opening today at four or tomorrow at ten — which one works better for you? And do you have insurance?', '오늘 4시나 내일 10시가 비는데, 어느 쪽이 더 편하세요? 그리고 보험은 있으세요?', '1ed7a4c12fab5dae487a9ca69485c44f04cee821049e5d154d242bfed3fccb8f'),
    (4096, 55, 8, 96, 'I don''t have insurance, so I''ll pay in cash.', '보험이 없어서 현금으로 낼게요.', 'I have an opening today at four or tomorrow at ten — which one works better for you? And do you have insurance?', '오늘 4시나 내일 10시가 비는데, 어느 쪽이 더 편하세요? 그리고 보험은 있으세요?', 'f03c761fe61ea5063e656fd41cfaabb92d41f74901acfbec44fc14d222a24572'),
    (4097, 55, 9, 97, 'I have a really sore throat, and it hurts to swallow.', '목이 너무 아프고, 침 삼킬 때 따가워요.', 'Thanks for calling the clinic. What symptoms are you having?', '네, 클리닉입니다. 어떤 증상 때문에 전화 주셨어요?', '6fb9d6dff8a4b42bd91d2c190363adc4d05a2b050bede1acd911b6e9ab7d8f75'),
    (4098, 55, 10, 98, 'The cough started Monday, and last night''s fever really knocked me out.', '기침은 월요일에 시작했고, 어젯밤엔 열 때문에 완전히 뻗었어요.', 'When did it start? Any fever along with the cough?', '언제부터 그러셨어요? 기침이랑 같이 열도 있으세요?', '957d7685852281b5d6546d944d9f5c11536333bf9f4968d935527e07a3ec24c5'),
    (4099, 55, 11, 99, 'Yes — is this visit covered?', '네 — 이번 진료는 보험 적용되나요?', 'Do you have insurance? Without it, the visit is sixty dollars.', '보험 있으세요? 없으시면 진료비는 60달러예요.', 'cf47c70cfe5a9e315cd103110edc1a3d7ad265452ef30161ab15b7707e26bb1c'),
    (4100, 67, 1, 100, 'I am a student here.', '저 여기 학생이에요.', 'Welcome! Do you study or work here?', '어서 오세요! 여기서 공부하세요, 아니면 일하세요?', '0dae6ddcd95ba3510f8c3eb10e73ebe6cabc86fba4ea692c4a574508cbd4b4d6'),
    (4101, 67, 2, 101, 'I need it for my rent.', '집세 내려고 필요해요.', 'What is this account for?', '이 계좌는 어디에 쓰실 거예요?', '90c8c71951a1bb66e0d8eda58186e578573a7611dba95537d48eaa97f9a82640'),
    (4102, 67, 3, 102, 'I have my passport right here.', '여권 여기 있어요.', 'I need your passport.', '여권이 필요해요.', '6bfae88fab82c031f58125dde5e15286910c6dae0239fc3a5a63af57d6714e08'),
    (4103, 67, 4, 103, 'I need it soon, please.', '빨리 받고 싶어요.', 'When do you need your card?', '카드는 언제까지 필요하세요?', '8be9633f55b528b29812ec90e7a98985877d0549e2071c68e3b6676aa6287633'),
    (4104, 67, 5, 104, 'I just moved here for a two-year master''s program.', '2년짜리 석사 과정 때문에 막 이사 왔어요.', 'Are you here for work or for study, and how long are you planning to stay?', '일 때문에 오셨어요, 공부 때문에 오셨어요? 그리고 얼마나 머무를 계획이세요?', '5d926a06917a9fd8b5ccd0240febf02654bf0ea3d87568c534299d2559adaf28'),
    (4105, 67, 6, 105, 'Mainly to get my salary from my new job.', '주로 새 직장 월급 받으려고요.', 'What will you mainly use the account for?', '계좌를 주로 어디에 쓰실 건가요?', 'd8bfcd0d2b9264864489cd9f7a122cdcba39e57cb83a6db8eceb73863286d9a2'),
    (4106, 67, 7, 106, 'Then I''ll take the simpler one with fewer fees.', '그럼 수수료 적고 더 간단한 걸로 할게요.', 'What will you mainly use the account for? I''ll recommend the one that fits you best.', '계좌를 주로 어디에 쓰실 건가요? 거기에 제일 맞는 걸로 추천해드릴게요.', 'e7b7e875ae3e4221fa256fa2fdc2453cff745dc6804bd3d7656d5476cbabb2e0'),
    (4107, 67, 8, 107, 'I''d like to have it by the end of the week.', '이번 주말까지는 받았으면 좋겠어요.', 'When do you need your card by?', '카드는 언제까지 필요하세요?', 'a20892b7ec4a82853eb06d965293ae0d183c6ab7201924c4d1d6363cacb86821'),
    (4108, 67, 9, 108, 'The student account fits better — my living expenses aren''t very big.', '학생 계좌가 더 맞을 것 같아요 — 제 생활비가 그렇게 많지는 않거든요.', 'We have a few options — what will you mainly be using the account for?', '몇 가지 있는데요 — 계좌는 주로 어떤 용도로 쓰실 건가요?', 'e2e8a9404ac9140b609948e0c1d4405fc4a6e13ac63489a92258c84149980a53'),
    (4109, 67, 10, 109, 'I''ll go with the student account — I don''t want to tie up my money in a minimum balance.', '학생 계좌로 할게요 — 최소 잔액에 돈을 묶어 두고 싶지는 않아서요.', 'What will you mainly be using the account for? I''ll recommend the one that fits you best.', '계좌는 주로 어떤 용도로 쓰실 건가요? 거기에 제일 맞는 걸로 추천해드릴게요.', 'b63b9d36d13d8c53b3c720368eb7cec64ce4fd4064e9456cac0b8978b534cd47'),
    (4110, 67, 11, 110, 'I have everything on me except the proof of address.', '거주 증명 빼고는 다 갖고 있어요.', 'I''ll need your passport, student ID, and proof of address — are those with you today?', '여권, 학생증, 거주 증명이 필요한데 오늘 다 갖고 계세요?', 'edb966f9fedc31b315e507c10ca4b1ebfb90b4e984a92a7f29ebeecdf26164d4'),
    (4111, 42, 1, 111, 'It will come around three o''clock.', '3시쯤에 올 거야.', 'What time will it come?', '몇 시에 와?', '08ee584f4f2651eca67b33a476121a76b20d5b5e27b929284c7b42614b3a142f'),
    (4112, 42, 2, 112, 'Thanks, but it''s a little heavy.', '고마워, 근데 그거 좀 무거워.', 'Okay, I can carry it. What time will it come?', '알았어, 내가 들어다 줄게. 몇 시에 와?', '4921853b29aec00ae90469ce5d344ad9a9fa624a3b7143735f305a1596736732'),
    (4113, 42, 3, 113, 'Yes, you can sign it for me.', '응, 네가 사인해도 돼.', 'Can I take it and sign your name?', '내가 받아서 네 이름으로 사인해도 돼?', 'a8064e12519b88446bb100784006af599f006f148a423a033f746eb500169469'),
    (4114, 42, 4, 114, 'That helps a lot, thank you.', '그거 정말 도움이 돼, 고마워.', 'Should I ask our neighbor?', '옆집에 받아달라고 할까?', '445de20d0437b980af685882b0b964b6f6c645c031a9478039eff8a253fd6276'),
    (4115, 42, 5, 115, 'Please be careful with the box, there''s glass inside.', '그 상자 조심히 다뤄 줘, 안에 유리 있어.', 'What time is it coming, and is there anything I should know?', '몇 시쯤 온대? 그리고 내가 알아둬야 할 게 있어?', 'ae6c13e04798dae7f8157bef19dc1a29adcefeb12df39c81f074054721e2f776'),
    (4116, 42, 6, 116, 'No, you don''t have to wait for me, I trust you.', '아니, 나 기다릴 필요 없어. 난 너 믿어.', 'Do you need to be there yourself, or can I just take it and sign your name?', '네가 직접 받아야 해? 아니면 내가 그냥 받아서 네 이름으로 사인해도 돼?', '8d0cb44b744b0a07b94e9e8f2c4bfec8e471764ec9a80873834ea1309f407ebf'),
    (4117, 42, 7, 117, 'If it comes late, just keep it in your room until tomorrow.', '늦게 오면 내일까지 네 방에 좀 둬 줘.', 'What should we do if it still hasn''t come?', '그때까지도 안 오면 어떻게 할까?', 'af1fb20fc8d9cdc344d037bfc759306b291b390e586f77b14a724d9e2c7948a4'),
    (4118, 42, 8, 118, 'Don''t worry, I''ll be home by seven, so I can take it then.', '걱정 마, 7시까지는 집에 올 테니까 그때 내가 받을게.', 'One problem, I have to go out at six. What should we do if it still hasn''t come?', '근데 하나 있어. 나 6시에 나가야 하거든. 그때까지도 안 오면 어떻게 할까?', '37d1262c5b8c23ca71426cead77acdb01ee08b9568fba0560c1730dab45966b6'),
    (4119, 42, 9, 119, 'Can you do me a favor and grab my package this afternoon?', '부탁 하나만 들어줄래? 오늘 오후에 내 택배 좀 받아줘.', 'Hey, what''s up?', '야, 무슨 일이야?', '8061b4fc7a8b794ad9112904b0c50e1cb88cc7da5d8d4a2c906238dfe9dcb3f6'),
    (4120, 42, 10, 120, 'Yeah, you''ll just need to sign for it.', '응, 수령 서명만 해주면 돼.', 'Anything I need to do when it gets here?', '받을 때 내가 뭐 해야 할 거 있어?', '0ef9e90f63e0a7dd85763d5eb2e73c16c1819b3ebacbc719158063a138b6439e'),
    (4121, 42, 11, 121, 'Yeah, I told them you''d sign on my behalf.', '응, 네가 나 대신 서명할 거라고 말해뒀어.', 'Is there anything I should know before it gets here?', '택배 오기 전에 내가 알아둘 거 있어?', 'a7663457a4601cd0de7f391f9dfeead063d45de2c9c34d34171fb2cb955335ad'),
    (4122, 62, 1, 122, 'I had it at the coffee shop.', '커피숍에서 가지고 있었어.', 'Where did you have your phone last?', '네 폰 마지막으로 어디에서 가지고 있었어?', 'e9b3581ba57518e87052d9bc633524f6bde40cf88716ff9453a9cf2ab46d77de'),
    (4123, 62, 2, 123, 'I should call my phone company right now.', '지금 바로 통신사에 전화해야겠어.', 'What should we do first?', '뭐부터 해야 할까?', '4ba28afb26c6704194775c54ce320f0ad7f2872a10427ada1656bd94e329a586'),
    (4124, 62, 3, 124, 'First, I will change my password.', '먼저 비밀번호를 바꿀게.', 'How can we keep them safe?', '그걸 어떻게 지킬 수 있을까?', '9d7df5ef5512555bc895f9bcff3bd0690a89b55fe1512e84291a617066c19297'),
    (4125, 62, 4, 125, 'That phone is old, but it''s important to me.', '그 폰 오래됐지만 나한테는 소중해.', 'Your phone has important things. How can we keep them safe?', '네 폰에 중요한 게 들어 있잖아. 그걸 어떻게 지킬 수 있을까?', '58d248c223c25f39d4d177099263bcbb9a65c69bb7552254156930856ebd56c0'),
    (4126, 62, 5, 126, 'The last time I saw it was when we left the bookstore.', '마지막으로 본 건 우리 서점에서 나올 때였어.', 'I''m calling your phone now, when did you use it last?', '내가 지금 전화해볼게. 마지막으로 언제 썼어?', 'd18df4873725b2ecb58ed33eaf9c2371c59cc8c996f9f11e5069f56ab24bcf03'),
    (4127, 62, 6, 127, 'I think I should report a lost phone to my carrier today.', '오늘 통신사에 휴대폰 분실 신고부터 하는 게 좋을 것 같아.', 'What do you think we should take care of first?', '뭐부터 처리해두는 게 좋을 것 같아?', '7c088dabf823777bafb8900b189fdc645ba28b99cfa1d54689575a866028cd1d'),
    (4128, 62, 7, 128, 'I need to sign out of my email from your laptop.', '네 노트북에서 내 이메일 로그아웃해야겠어.', 'How can we protect your accounts?', '계정은 어떻게 보호하지?', '43fc9b592c032070922e3559c0dbb6f31dd7718e9cd76d8183308694060a80ba'),
    (4129, 62, 8, 129, 'There are work files on it, so I want to keep my data safe.', '업무 파일이 들어 있어서 내 정보를 안전하게 지키고 싶어.', 'Is there anything important on your phone? How can we protect your accounts?', '폰에 중요한 거 있어? 계정은 어떻게 보호하지?', 'ce0db1d9b1e82530dbecab14b3f8fd77d7ee1da62e887a3c3e6ee8b3779472cb'),
    (4130, 62, 9, 130, 'No idea — let''s retrace my steps from the library.', '모르겠어 — 도서관에서부터 내가 갔던 길을 되짚어 보자.', 'Okay, stay calm — any idea where it could be?', '좋아, 침착하게 — 어디 있을지 짐작 가는 데 있어?', '4ee359925881579d7f2e3f380e2f64a467b744afea6895b1295b2715dd8f89e1'),
    (4131, 62, 10, 131, 'Don''t worry — it''ll turn up somewhere.', '걱정 마 — 어디선가 나타날 거야.', 'What if we can''t find it today?', '오늘 못 찾으면 어떡하지?', '6d5461c4548a2504e08f27d67160d6f56c2a8fc8cf27befd6ec696949f38d5d2'),
    (4132, 62, 11, 132, 'Yes! I can track it down with my tablet.', '응! 태블릿으로 위치를 추적해서 찾을 수 있어.', 'I''ll call your phone right now — is it connected to any other device?', '내가 지금 네 폰으로 전화해볼게 — 연결된 다른 기기 있어?', '2eb0f28657576dcb28f86c9c48f780472526bd13148d3858d560d6e54417c330'),
    (4133, 52, 1, 133, 'Let''s try again in five minutes.', '5분 뒤에 다시 해 보자.', 'Oh no, the printer is not working! What should we do?', '어떡해, 프린터가 안 돼! 우리 어떻게 하지?', '755543d7346e4796e699de720454d3cc701a08a5e1c9b550d9d785c7219b9cbd'),
    (4134, 52, 2, 134, 'I have it on a USB.', 'USB에 담아 왔어.', 'Let''s use another computer. Can you email it?', '다른 컴퓨터를 쓰자. 이메일로 보낼래?', '339295a9009a6e20132f5c04744fc5c9c65987d31992bdcaaf1fefda953c1be5'),
    (4135, 52, 3, 135, 'Yes, let''s go before class starts.', '응, 수업 시작하기 전에 가자.', 'It will print in ten minutes. Can you come with me to tell the office?', '10분 뒤에 출력돼. 사무실에 고장났다고 말하러 같이 가줄래?', 'e1985fb09a10b00c5f1a2ee53c52dab0cab111b7f7e1faa9e4938198b3a3b031'),
    (4136, 52, 4, 136, 'I think the printer is jammed, so let''s open the tray.', '프린터에 종이가 걸린 것 같아. 트레이 한번 열어 보자.', 'The printer keeps showing a paper error, and our deadline is really close. What should we try first?', '프린터에 자꾸 용지 오류가 뜨는데 마감이 코앞이야. 뭐부터 해볼까?', 'fe8c9dcbcde8b2cddcdd015e6c5848fa8269efc3475f35e373a7fa8740e2bced'),
    (4137, 52, 5, 137, 'I''ll attach the file to an email right now.', '지금 바로 이메일에 파일 첨부해서 보낼게.', 'Moving your file to another computer might be faster. What''s the easiest way for me to get it?', '파일을 다른 컴퓨터로 옮기는 게 더 빠를 것 같아. 내가 그 파일을 어떻게 받는 게 제일 편해?', 'f2254da21636b879670132b083221f2dd075f346cce07b25ca0dd059c0dbfff5'),
    (4138, 52, 6, 138, 'Could I borrow your laptop for about ten minutes?', '네 노트북 10분만 빌려도 될까?', 'Moving your file to another computer might be faster. What''s the easiest way for me to get it?', '파일을 다른 컴퓨터로 옮기는 게 더 빠를 것 같아. 내가 그 파일을 어떻게 받는 게 제일 편해?', 'dc4dfd3de5503426251cd49a11942117c1cb8c0475dd4cab2d4144a1f502d2d2'),
    (4139, 52, 7, 139, 'Let''s go now so we make it in time.', '지금 가자, 그래야 늦지 않아.', 'The printout will be ready in about ten minutes. Should we go tell the office it''s broken?', '출력물은 10분쯤 뒤에 나와. 사무실에 고장났다고 말하러 같이 갈까?', '8a78fc09b85c0162d7f42177d3a417b61133e7cee578712d591b6b89db286666'),
    (4140, 52, 8, 140, 'I think it''s completely out of order.', '아무래도 완전히 고장 난 것 같아.', 'Oh no — the printer''s showing a paper error and the deadline''s coming up fast. What should we try first?', '큰일났다, 프린터에 용지 오류가 떴는데 제출 시간이 얼마 안 남았어. 뭐부터 해볼까?', '7361b1df74cd4e713f332d34dc911b8003635efd9a748616ec3276de6033246a'),
    (4141, 52, 9, 141, 'Yes! It finally spat out my assignment.', '응! 드디어 내 과제를 뱉어냈어.', 'Is the printer working again?', '프린터 다시 되는 거야?', 'a3d35c094974dbf29e0b13060f6c9c32b9e58716fc9c38bdeadb5c748553ae70'),
    (4142, 52, 10, 142, 'If we hurry, we can still beat the deadline.', '서두르면 아직 마감 전에 낼 수 있어.', 'It''ll print in about ten minutes. Want to come with me to the office after?', '10분쯤이면 출력돼. 끝나고 사무실에 같이 갈래?', '2d5168935767498e91cc787cb8b85899f0ae2d1b837ccc7ed3d9b05c24ca24ee'),
    (4143, 46, 1, 143, 'That''s okay. I''ll be back at six.', '괜찮아요. 6시에 다시 올게요.', 'Sorry, the lockers are full.', '죄송해요, 보관함이 다 찼어요.', '970744add1697065647a5ce83466b3ceaaff11a3e4aa9bcc3b454527412f2287'),
    (4144, 46, 2, 144, 'It''s very big and heavy.', '아주 크고 무거워요.', 'How big is your bag?', '가방이 얼마나 큰가요?', '15786ffa343b832f40b658c4f49c5d4c8527dfe8d4f5d8c425dc91a98f82cc3e'),
    (4145, 46, 3, 145, 'I will take the cheap one.', '싼 쪽으로 할게요.', 'Do you want the near shop or the cheaper shop?', '가까운 가게로 하시겠어요, 더 싼 가게로 하시겠어요?', '76e391a83d173e1919c9a81ad5714feb4bc00fdaf5c5f4e5ab91ee2f884d1ab7'),
    (4146, 46, 4, 146, 'Yes. What time do you close?', '네. 몇 시에 문 닫아요?', 'You need this ticket for your bag. Any questions?', '가방 찾으실 때 이 표가 필요해요. 궁금한 거 있으세요?', 'fdc18bb111e2105f42f1bce56db6f99174bca0166d3d98eac5e05718d9dff430'),
    (4147, 46, 5, 147, 'I''ll need it around five, and it''s about this big.', '5시쯤에 필요하고, 크기는 대략 이 정도예요.', 'I''m afraid all the lockers are full right now. What time will you need your bag, and what size is it?', '죄송하지만 지금 보관함이 다 찼어요. 가방은 몇 시에 필요하시고, 크기는 어느 정도예요?', '3d709872d25f5394fcde623e5dbc1be5f5ae60edb8345ee141b4c75691516bde'),
    (4148, 46, 6, 148, 'I''ll take the cheaper one, even if it''s ten minutes away.', '10분 거리라도 더 싼 곳으로 할게요.', 'There''s a storage shop right outside the station for £8, and a cheaper one for £4. Which fits your plans better?', '역 바로 앞에 8파운드짜리 보관소가 있고, 4파운드짜리 더 저렴한 곳이 있어요. 일정상 어느 쪽이 더 나으세요?', '443ed9e7c1460901257a00c65295721cf4b997b9f494672f2dccafdf719c9d22'),
    (4149, 46, 7, 149, 'So I show this ticket when I collect my bag?', '그럼 가방 찾을 때 이 보관증을 보여 드리면 되나요?', 'You''ll need this ticket to get your bag back. Is there anything else you''d like to know?', '가방을 찾으실 때 이 보관증이 필요해요. 더 궁금하신 점 있으세요?', '784eec77cbdbf75fdf0ba7c872519fc67f8cfcb1e707e22a49c47d37fb3874e7'),
    (4150, 46, 8, 150, 'Yes, are you open until ten tonight?', '네, 오늘 밤 10시까지 여시나요?', 'Is there anything else you''d like to know?', '더 궁금하신 점 있으세요?', '2d2bb27e16ee03efffbf8aace3256c751ba9965af562d069e03acca83105396f'),
    (4151, 46, 9, 151, 'Could I just leave my bag with you until five?', '그럼 5시까지 가방을 여기 맡겨둘 수 있을까요?', 'I''m afraid the lockers are all full at the moment — shall I find you an alternative?', '죄송하지만 지금은 보관함이 다 찼어요 — 다른 방법을 찾아드릴까요?', 'd77f237e9d335e4808babdc0edf0db82feae0dbec950c700467be8dfbe9de530'),
    (4152, 46, 10, 152, 'I''ll come back for it around six.', '6시쯤 찾으러 다시 올게요.', 'What time will you be picking up your bag?', '가방은 몇 시쯤 찾으러 오실 예정이세요?', '9c75ef81a563124ecebee58fcd6be65f177736bab71f5a70caec99327e9a8dfe'),
    (4153, 46, 11, 153, 'If it saves money, it''s worth the walk.', '돈을 아낄 수 있으면 좀 걸어갈 만해요.', 'There''s a storage shop right nearby that''s a bit pricey, and a cheaper one about ten minutes away. Which works better for you?', '바로 근처엔 조금 비싼 보관소가 있고, 걸어서 10분쯤엔 더 저렴한 곳이 있어요. 어느 쪽이 나으세요?', 'ad429962c23636dc53ad97e718b14e168a44bd54cc7c4cde3a17f693fc7bc382'),
    (4154, 56, 1, 154, 'Don''t worry. I''ll call them now.', '걱정 마. 내가 지금 전화할게.', 'Wait, this is not our food. What should we do?', '잠깐, 이건 우리 음식이 아니야. 어떻게 하지?', '2d5b448d7158037355910dd80be4c9a56a8069d602bb46983456ecdc00b7aa2d'),
    (4155, 56, 2, 155, 'No. I want my money back.', '아니. 나는 돈 돌려받고 싶어.', 'They can bring our food in one hour. Is that okay?', '한 시간 뒤에 우리 음식을 가져다줄 수 있대. 괜찮아?', 'bc5b48e6eee380f77f8a2f3fceaac9af3e44dfc09d9cb58ac451afd7c075758f'),
    (4156, 56, 3, 156, 'One hour? That''s too long.', '한 시간이나? 그건 너무 오래 걸려.', 'They can bring our food in one hour.', '한 시간 뒤에 우리 음식을 가져다줄 수 있대.', 'f891681fddb2d12b0e666eb3f02156da9f485a9a26288b2d3475576996029cc6'),
    (4157, 56, 4, 157, 'Let''s play a game on my phone.', '내 폰으로 게임 하자.', 'We will wait one hour. What can we do now?', '한 시간 기다려야 해. 우리 뭐 할까?', 'b96806f980b8e1d8ba2143c83070f9b38753e42763eb2303f785aea14c6260fd'),
    (4158, 56, 5, 158, 'Let''s take a photo of the wrong order first.', '일단 잘못 온 주문 사진부터 찍자.', 'Wait, this isn''t what we ordered. What should we do about it?', '잠깐, 이건 우리가 시킨 게 아니야. 이거 어떻게 하지?', '54fbf6ccb8ad4d3e53df688ceb1bceeba44f218baa1587f6277af5dd7d02683e'),
    (4159, 56, 6, 159, 'I''ll call customer service and ask for a refund.', '고객센터에 전화해서 환불해 달라고 할게.', 'This isn''t what we ordered. What should we do about it?', '이건 우리가 시킨 게 아니야. 이거 어떻게 하지?', 'ddd23024f2fd974179af81c5edaa24042b295ee045ba67062b3396f4ecdce4fd'),
    (4160, 56, 7, 160, 'A refund sounds better than waiting an hour.', '한 시간 기다리는 것보다 환불이 나을 것 같아.', 'They can deliver the right food in an hour, or refund us right away. Which one should we pick?', '한 시간 안에 제대로 다시 배달해주거나, 바로 환불해준대. 어느 쪽으로 할까?', 'e1f9e579913a7e32404f6c65fedfe92a31e0cf3d720191fa9a871e91f378252e'),
    (4161, 56, 8, 161, 'Let''s put on some music and set the table.', '음악 좀 틀고 상 차리자.', 'Either way, we''ll be waiting a while. What should we do while we wait?', '어느 쪽이든 좀 기다려야 해. 기다리는 동안 뭐 하면 좋을까?', '511fc3afd4925a81ad10090b76f57981a88554e65b16eb1c8beddaf680578c6a'),
    (4162, 56, 9, 162, 'Let''s take the redelivery — their food is worth the wait.', '재배달로 하자 — 거기 음식은 기다릴 만하잖아.', 'Support says they can redeliver within an hour, or refund us right away. Which should we go with?', '고객센터에서 한 시간 안에 재배달해주거나 바로 전액 환불해줄 수 있대. 어느 쪽으로 할까?', 'd475ac57bbedab80057bb037850e15a271871e25ca330da38e7c49ec636e66df'),
    (4163, 56, 10, 163, 'Let''s open those chips — they should tide us over until the food comes.', '저 과자라도 뜯자 — 음식 올 때까지는 그걸로 버틸 수 있을 거야.', 'Either way it''ll take a while. What should we do about dinner in the meantime?', '어느 쪽이든 시간이 좀 걸리겠다. 그동안 저녁은 어떻게 할까?', '5adebdd28cd4dc75c43be5d6e679f235e50caac5e3bfe87a7b886d7212cf722b'),
    (4164, 56, 11, 164, 'This is a mistake on their end, so they have to fix it.', '이건 그쪽 실수니까, 걔네가 해결해줘야지.', 'Wait, this isn''t what we ordered. What should we do?', '잠깐, 이거 우리가 시킨 게 아니야. 어떻게 하지?', 'd05f21dac7b966e2807d16c9c3d6b4f19a357839b9762a01945c6cdd864d4464'),
    (4165, 70, 1, 165, 'My flight to Rome leaves at six.', '로마로 가는 제 비행기는 6시에 떠나요.', 'Where are you going?', '어디로 가세요?', '03004a7de41b9e1969ad8a80c7a06b129aa10e5cd6d3ba637eb6101ffe09d575'),
    (4166, 70, 2, 166, 'My name on my passport is Minji Kim.', '제 여권에는 이름이 Minji Kim으로 되어 있어요.', 'Please spell your passport name.', '여권에 있는 성함 철자를 말씀해 주세요.', 'fcf0a33480ffc3201f4f55ce8d0d30a38c9c8970fe1a81be75bfd1873f99ca0d'),
    (4167, 70, 3, 167, 'I want a cheaper seat, please.', '더 싼 좌석으로 주세요.', 'Is a more expensive seat okay?', '더 비싼 좌석도 괜찮으세요?', '92cc285b6d8b3d951e94558ba70e071f5b75a3f40c4dd87558b02d96aa1ec0da'),
    (4168, 70, 4, 168, 'I will take the later flight.', '저는 더 늦은 항공편으로 할게요.', 'But you must wait seven more hours. Which one do you want?', '대신 7시간을 더 기다리셔야 해요. 어느 걸로 하시겠어요?', '636992a598e8facc20a1ec7efd5f443d58565738a67247a38540ecd99898e6e9'),
    (4169, 70, 5, 169, 'It''s spelled J-I-H-O, and my last name is Park.', '철자는 J-I-H-O이고, 성은 Park이에요.', 'How is your name written on your passport?', '여권에는 성함이 어떻게 적혀 있나요?', 'c9c9a02a6653754f75aaaa5de7c0378816e6db96af80e4834182dca6b17cae10'),
    (4170, 70, 6, 170, 'I checked the booking, and one letter is wrong in my first name.', '예약을 확인해 봤는데, 제 이름에서 글자 하나가 틀렸어요.', 'Let me find your booking. How is your name written on your passport?', '예약을 찾아볼게요. 여권에는 성함이 어떻게 적혀 있나요?', '2f5cc2c033f11af614ef94f85236c745b05afebadf9f5ed68859f81ca05264eb'),
    (4171, 70, 7, 171, 'I''m sorry, but business class is out of my budget.', '죄송하지만 비즈니스석은 제 예산을 넘어요.', 'Only business class is left. Is that all right?', '지금 비즈니스석만 남았는데 괜찮으세요?', '50e6a7ea065b76f0acfa5e40955c89cf436e102fa46a3c450df771b18487b176'),
    (4172, 70, 8, 172, 'I''ll go with the other airline, since it''s cheaper.', '더 싸니까 다른 항공사로 할게요.', 'Another airline flies to the same city thirty minutes later for a lower price. Which one would you like?', '다른 항공사가 30분 뒤에 같은 도시로 가는데 가격이 더 저렴해요. 어느 걸로 하시겠어요?', '5b4a46b9a80c99bbac0dc2455f26793842f5dccc55fc937c2bd9da04adc0d89a'),
    (4173, 70, 9, 173, 'It''s Seoul. My passport says JIYU KIM, so the booking must have a typo.', '서울이요. 여권에는 JIYU KIM으로 돼 있는데, 예약에 오타가 난 것 같아요.', 'Let me pull up your booking. Could you tell me your destination and the exact name on your passport?', '먼저 예약을 확인해볼게요. 목적지랑 여권에 있는 영문 이름을 정확히 말씀해 주시겠어요?', '129bf3b2b9d316b4212d0a5be59853b876280dd5d6d2b6327a7be7db5c1c9123'),
    (4174, 70, 10, 174, 'The name doesn''t match my passport — one letter is different.', '이름이 제 여권과 일치하지 않아요 — 한 글자가 달라요.', 'Could you tell me exactly what''s wrong with the name on the ticket?', '티켓에 있는 이름이 정확히 어떻게 잘못됐는지 말씀해 주시겠어요?', '690fb8f8c3c403e52085d3f33b240b451fcce30994cd892cb27c8948595d1680'),
    (4175, 70, 11, 175, 'If it''s half the price, I''ll wait it out for seven hours.', '절반 가격이면 7시간쯤은 버티고 기다릴게요.', 'There''s a seat on a later flight at about half the price, but it leaves seven hours after this one. Which one would you like?', '같은 목적지로 가는 절반 가격 좌석이 있는데, 이 편보다 7시간 뒤에 출발해요. 어느 걸로 하시겠어요?', '17d99a51cd6e12645bb2654d88851cd8712c2adb7b5cbe50056d63d1122eaa26'),
    (4176, 48, 1, 176, 'I know a good place near the river.', '강 근처에 좋은 데 알아.', 'The weather will be nice this weekend. Where should we go?', '이번 주말에 날씨가 좋대. 우리 어디로 갈까?', '5c2af239b5378bf15d2991347f69726bf07c83038648eb530d1b542438ed8db5'),
    (4177, 48, 2, 177, 'I will bring some snacks and juice.', '나는 간식이랑 주스 가져갈게.', 'I have sandwiches and a blanket. What will you bring?', '난 샌드위치랑 돗자리 있어. 넌 뭐 가져올래?', '43c44fbc18f602c551226f043e22183b0b4e3af0f1dc0bf03c35118d38ae8e97'),
    (4178, 48, 3, 178, 'Let''s watch a movie at my house.', '우리 집에서 영화 보자.', 'What should we do then?', '그러면 뭐 할까?', 'd919eee9aaf5e779c583461d7b1f9ab7bbaf3096be11f1820df384dffc145a72'),
    (4179, 48, 4, 179, 'On a rainy day, we can go to a cafe.', '비 오는 날엔 카페에 가면 되지.', 'It may rain that day. What should we do then?', '그날 비가 올 수도 있어. 그러면 뭐 할까?', 'e156d1c6bea6eaee48d70d23f0414daee6f99863962e71bb8d46aa9799b96c80'),
    (4180, 48, 5, 180, 'There''s a nice spot by the lake with shade.', '호수 옆에 그늘진 괜찮은 자리가 있어.', 'Where do you think we should have our picnic?', '피크닉은 어디서 하면 좋을 것 같아?', '1318225e94bd76d8226a9af376e31ff81a7d410e8280a86d1f742c4d22fe8dce'),
    (4181, 48, 6, 181, 'I''ll bring something to drink, maybe iced tea and water.', '마실 거 가져갈게, 아이스티랑 물 정도로.', 'I''m bringing sandwiches and a blanket. What would you like to bring?', '난 샌드위치랑 돗자리 가져갈게. 넌 뭘 가져오고 싶어?', '42c9027f4abae3705ef3bc3f96f724e160a6e4cf306946ef27c50e3df34b4647'),
    (4182, 48, 7, 182, 'Let''s check the forecast the night before and decide then.', '전날 밤에 일기예보 확인하고 정하자.', 'They say it might rain that day, though. What should we do then?', '근데 그날 비가 올 수도 있대. 그러면 뭘 하면 좋을까?', '4c1b83fe86a515d0fb1a34e2e94524beb99c5f473be5f567f11648004f68a8d4'),
    (4183, 48, 8, 183, 'If it rains, let''s just do it some other day.', '비 오면 그냥 다른 날에 하자.', 'What should we do then?', '그러면 뭘 하면 좋을까?', '325dba81d779cd96679dcf0eee908a2386d81f8a2abb46e925b7bd532973f737'),
    (4184, 48, 9, 184, 'I''ll pack some fruit and drinks for us.', '내가 과일이랑 마실 것 좀 싸 갈게.', 'I''ll bring sandwiches and a blanket. What are you going to bring?', '난 샌드위치랑 돗자리 가져갈게. 넌 뭐 가져올래?', '96f011d884d34fabc20c8f7b45c72dfbf19d8a2c7cdcd3de1c0c6a74c33ba1d8'),
    (4185, 48, 10, 185, 'Let''s bring an umbrella anyway, just in case.', '그래도 혹시 모르니까 우산 하나 가져가자.', 'The weather''s supposed to be perfect — anything else we should bring?', '날씨는 완전 좋을 거라던데 — 그거 말고 더 챙길 거 있을까?', 'af0eb5e93ffd8b2bf76a79ec92559ae0c065225359b7c7056e70aaf686297a3a'),
    (4186, 48, 11, 186, 'Then let''s move the picnic indoors and eat in the lounge.', '그럼 피크닉을 실내로 옮겨서 라운지에서 먹자.', 'And just in case it rains — what should we do instead?', '그리고 혹시 비 오면 — 대신 뭘 할까?', 'e891e3272c06e19593acc0df4e37dcc3ca648ab0c464700c9d396878eb122f62'),
    (4187, 45, 1, 187, 'I play soccer with my friends.', '나는 친구들이랑 축구 해.', 'Let''s exercise together after class! What sport do you like?', '수업 끝나고 같이 운동하자! 너는 무슨 운동을 좋아해?', '298bb3f8d336ae94b4428cea83af704bab9ee38f42bf571b8bb749434429dc4e'),
    (4188, 45, 2, 188, 'I want to get strong and fast.', '나는 튼튼하고 빨라지고 싶어.', 'Why do you want to exercise?', '너는 왜 운동을 하고 싶어?', '160c55bda0cdea5a586b6d462d52526fb57a29d0f71a3a8a058a251f3733b2ca'),
    (4189, 45, 3, 189, 'I exercise to stay healthy.', '나는 건강하게 지내려고 운동해.', 'Why do you want to exercise?', '너는 왜 운동을 하고 싶어?', 'feb83d501d7711d45c1278d45768984c0de9eb7d967b13976e3490f53f6077cc'),
    (4190, 45, 4, 190, 'We can play in the park after class.', '수업 끝나고 공원에서 하면 되겠다.', 'When and where can we meet?', '우리 언제, 어디서 만날까?', '9ae36538dcd1a26012e8dc92925c38d1d1cdd0218d228782d88e0ab9d2fa1481'),
    (4191, 45, 5, 191, 'I prefer swimming to running because it''s easier on my knees.', '무릎에 덜 무리가 가서 달리기보다 수영이 더 좋아.', 'What kind of exercise do you enjoy the most?', '어떤 운동을 제일 즐겨 해?', '53c88eb9c61ab4e7ba16e4b18e4fcbfcf65149aefbd3bd601c1729fd719e793a'),
    (4192, 45, 6, 192, 'I just want to have more energy during the day.', '낮 동안 기운이 더 났으면 좋겠어.', 'People exercise for different reasons. What do you hope to gain from it?', '사람마다 운동하는 이유가 달라. 너는 운동으로 무엇을 얻고 싶어?', 'f381ce7e1799936d59b05cbdbd92ca9e85a2f3f21498990068b4d344a9310697'),
    (4193, 45, 7, 193, 'I want to try something new instead of the same routine.', '늘 하던 것 말고 새로운 걸 해보고 싶어.', 'What do you hope to gain from it?', '너는 운동으로 무엇을 얻고 싶어?', '1142d97f273068040dafdec44a22b32b3735ee8beeade7bd35e8b577be02a3cf'),
    (4194, 45, 8, 194, 'Let''s meet in front of the gym at six.', '6시에 헬스장 앞에서 만나자.', 'Then let''s plan it. What time and place would be easiest for you?', '그럼 계획을 세우자. 너한테 가장 편한 시간과 장소는 어디야?', '2beb1fba784fc43a10ca33dc95cd2d4ad64a6acd8a1256a3621f696b11ebef9c'),
    (4195, 45, 9, 195, 'I just want to get in shape before summer.', '난 그냥 여름 전에 몸 만들고 싶어.', 'What about you — what do you want to get out of it?', '넌 어때 — 운동으로 뭘 얻고 싶어?', 'd9854bac6796b98d5b01626a3c53b97679ca3730bf7d581e7fc678653610b0fd'),
    (4196, 45, 10, 196, 'Let''s hit the gym right after class.', '수업 끝나자마자 헬스장 가자.', 'Fair warning — I go pretty hard. When and where works for you?', '미리 말해두는데 나 운동 빡세게 해. 언제 어디서 볼까?', 'f5305160a8824f9d218efe6c201e909181acac661a8311256d0c0ce1887cd8a9'),
    (4197, 45, 11, 197, 'Same here — I want to build muscle in my arms.', '나도 — 팔 근육을 키우고 싶어.', 'My goal is to bulk up a bit. What about you — what do you want to get out of it?', '난 몸 좀 키우는 게 목표야. 넌 어때 — 운동으로 뭘 얻고 싶어?', '7fd6e7e29c75ddcfa50a45affdc117d3ba3f4c62779b931d0da57beee8ee62bc'),
    (4198, 60, 1, 198, 'I like the sea the most.', '난 바다가 제일 좋아.', 'We need three nature photos. Do you like the sea or mountains?', '자연 사진 세 장이 필요해. 넌 바다가 좋아, 산이 좋아?', 'dee4bc6b7a832e18b2257e9068f08e49fbad839b82976e37baefdaf058d49564'),
    (4199, 60, 2, 199, 'Let''s take them before sunset.', '해 지기 전에 찍자.', 'Nice! When and where should we take them?', '좋다! 언제 어디서 찍을까?', 'c31a55968abc7d3343874df6c473cd23df8857e801f12a7ded00955b12737078'),
    (4200, 60, 3, 200, 'We can take photos near the river.', '강 근처에서 사진 찍으면 돼.', 'Nice! When and where should we take them?', '좋다! 언제 어디서 찍을까?', 'b519b85b17010faeee78c744668c1d3de5ddcbe62a122ba434a757de3896aa3c'),
    (4201, 60, 4, 201, 'I use my phone for photos.', '난 사진은 폰으로 찍어.', 'Do you have a camera? You can use mine.', '카메라 있어? 없으면 내 거 써도 돼.', '4e83822b78288c9fd9ef636407fde46b5c3309aae4ccc2893f88e7ae08cedb94'),
    (4202, 60, 5, 202, 'I love wide open spaces more than city streets.', '난 도시 거리보다 탁 트인 넓은 곳이 훨씬 좋아.', 'For class we have to turn in three photos of scenery. What kind of scenery do you like best?', '수업에서 풍경 사진 세 장을 내야 해. 넌 어떤 풍경을 제일 좋아해?', '70c1a5d4bce72bbc7235a55c52dbfa9f8c0590ea21b01cb9e938ae6bc23fd0a6'),
    (4203, 60, 6, 203, 'The best time to go is early morning, when the light is soft.', '가기 제일 좋은 때는 이른 아침이야. 그때 빛이 부드럽거든.', 'Nice. When and where should we take them so they look their best?', '좋다. 제일 잘 나오게 찍으려면 언제, 어디서 찍는 게 좋을까?', 'e52b59d16161050fbca28675302ecbbc6b4b8be029f4bec66953246027659261'),
    (4204, 60, 7, 204, 'The view from the hill behind school is the best.', '학교 뒤 언덕에서 보이는 경치가 제일 좋아.', 'Nice. When and where should we take them so they look their best?', '좋다. 제일 잘 나오게 찍으려면 언제, 어디서 찍는 게 좋을까?', '317f9ebff4a087bcbee348a45176473623640212f3751d76839840b3c6605669'),
    (4205, 60, 8, 205, 'I have an old one, but yours is better.', '나도 오래된 게 하나 있긴 한데, 네 게 더 나아.', 'Do you have a camera? If not, I can lend you mine.', '카메라 있어? 없으면 내 걸 빌려줄게.', 'aaee46218fd1356d9a2278b551193ea11dbf55f5a18e41b64f0cdcc7a29bd087'),
    (4206, 60, 9, 206, 'Let''s divide up the work — you scout spots, I''ll handle the gear.', '일을 나누자 — 넌 장소 찾고, 장비는 내가 챙길게.', 'We''ve still got two more shots to get — how do you want to handle the rest?', '아직 두 장 더 찍어야 하는데 — 나머지는 어떻게 할까?', '84d994337b3138b1fc1c0b96fe4777b9af7cc4f18141b840313f695131b0e8ec'),
    (4207, 60, 10, 207, 'Let''s shoot during golden hour, right before sunset.', '해 지기 직전 골든아워에 찍자.', 'When should we shoot to really capture that?', '그 풍경을 제대로 담으려면 언제 찍는 게 좋을까?', '047be3184f4a6cd8656221b5db074e107305424201bfb36844f661e1d955f949'),
    (4208, 60, 11, 208, 'I love foggy mountains in the morning — they''re breathtaking.', '난 아침에 안개 낀 산이 좋아 — 진짜 숨 막히게 아름답거든.', 'So we need to submit three photos of our favorite scenery. What kind of scenery do you love most?', '좋아하는 풍경 사진 세 장을 내야 해. 넌 어떤 풍경을 제일 좋아해?', 'b80ef87f9c63846c6911a3c26733015cd3a1863a120aef5c791db789e6d376a4'),
    (4209, 59, 1, 209, 'Can I add a bottle of water?', '물 한 병 더 담아도 될까요?', 'Your coupon needs five more dollars. What would you like to do?', '쿠폰을 쓰시려면 5달러가 더 필요해요. 어떻게 하시겠어요?', '889d01607913187be6c23776a7de081dd80038012013939903ae0ac14750e69c'),
    (4210, 59, 2, 210, 'I will pay without the coupon.', '그냥 쿠폰 없이 결제할게요.', 'Your coupon needs five more dollars. What would you like to do?', '쿠폰을 쓰시려면 5달러가 더 필요해요. 어떻게 하시겠어요?', 'b69e21154bb20e002383915dd3a96ae72194b27a572ff84f91fc0db651114a91'),
    (4211, 59, 3, 211, 'I will buy one more item.', '그럼 하나만 더 살게요.', 'Spend twenty more dollars today. Then you get a fifteen dollar coupon next time. Do you want to buy more?', '오늘 20달러어치 더 사시면 다음에 쓸 수 있는 15달러 쿠폰을 드려요. 더 사시겠어요?', 'aa5b64f52897b94fcbfa0b51f031ea9673051a9791ee84335df0e4e458e00403'),
    (4212, 59, 4, 212, 'Yes, here is my phone number.', '네, 제 전화번호 여기요.', 'All done! Do you want points today?', '결제 다 됐어요! 포인트 적립해 드릴까요?', '54bd0963c318ef55a6fb907e03a0190089250ac69291551506752f27c673616c'),
    (4213, 59, 5, 213, 'How much more do I need to get the discount?', '할인받으려면 얼마나 더 사야 하나요?', 'The coupon is valid, but you''re a little under the minimum. Would you rather add a small item or pay without the discount?', '쿠폰은 유효한데 최소 결제 금액에 조금 모자라요. 작은 상품을 하나 추가하시겠어요, 아니면 할인 없이 결제하시겠어요?', 'acf413f0fa06b681c57bf7b13665d5a33e8e3cbe921d29571ce305d118e0ec0b'),
    (4214, 59, 6, 214, 'I''d rather pay full price than buy something I don''t need.', '필요 없는 걸 사느니 그냥 정가로 낼게요.', 'The coupon is valid, but you''re a little under the minimum. Would you rather add a small item or pay without the discount?', '쿠폰은 유효한데 최소 결제 금액에 조금 모자라요. 작은 상품을 하나 추가하시겠어요, 아니면 할인 없이 결제하시겠어요?', 'e71d033658ce7f041b6b83277dc3a1d7b3b2280233d5cf769a9673f421437786'),
    (4215, 59, 7, 215, 'It''s a good deal, so I''ll add a few more snacks.', '괜찮은 조건이네요, 그럼 간식 몇 개 더 담을게요.', 'One more thing — spend forty dollars today and you''ll get a fifty-dollar coupon next time. Would you like to add anything?', '한 가지 더 알려드리면 — 오늘 40달러를 더 구매하시면 다음에 쓸 수 있는 50달러 쿠폰을 드려요. 더 담으시겠어요?', 'a49679b6e116b465d13e1e53b51382dfa35c36d1dce6a14d0319f257715099df'),
    (4216, 59, 8, 216, 'Yes, please use my membership so I can earn points.', '네, 멤버십 써서 포인트 적립해 주세요.', 'All set! Would you like to use your membership today, and do you need a receipt?', '결제 끝났습니다! 오늘 멤버십 쓰시겠어요? 영수증은 필요하세요?', '7ab50a1ad618e1b25cf117022c60ede4dd82981404c95d6f64fb901f8966bf8b'),
    (4217, 59, 9, 217, 'Yes — but before you ring it up, could you check this coupon?', '네 — 근데 찍기 전에 이 쿠폰 좀 확인해 주시겠어요?', 'Is that everything for you today?', '오늘 구매하실 건 이게 다인가요?', '1a90ffedb736baf0325f6e70e942eeba6bb4cdc675ba7b5b1171d5e7bfa39454'),
    (4218, 59, 10, 218, 'I''ll add this chocolate to meet the minimum.', '최소 금액 채우게 이 초콜릿을 추가할게요.', 'You could add something small to qualify, or pay full price without the coupon — what would you like to do?', '작은 상품을 하나 추가해서 조건을 맞추셔도 되고, 아니면 쿠폰 없이 정가로 결제하셔도 돼요 — 어떻게 하시겠어요?', 'a72392405259d22a6f03555ff26dc4f0cd8918098a2facbc1b1a99c707fde34c'),
    (4219, 59, 11, 219, 'Oh no — how much am I short?', '아 이런 — 얼마나 부족한데요?', 'Let me check… ah, the coupon''s valid, but your total doesn''t quite reach the amount you need — would you like to add something?', '확인해볼게요… 아, 쿠폰은 유효한데 결제 금액이 조건에 조금 못 미치네요 — 뭐 하나 추가하시겠어요?', 'a1da603eb8b328c562afdc61f77ff41ae2baf67cda0a3e4be00ccfa4648943dd'),
    (4220, 51, 1, 220, 'The machine stopped after the apples.', '사과를 찍고 나서 기계가 멈췄어요.', 'Okay, I can help you. What happened here?', '네, 도와드릴게요. 여기 무슨 일이에요?', '9062d2dbbfcfdda8b287f273eb71a60d2fd413633c979580db2da1b98ebc355c'),
    (4221, 51, 2, 221, 'I press the button many times.', '버튼을 여러 번 눌러 봐요.', 'Okay, I can help you. What happened here?', '네, 도와드릴게요. 여기 무슨 일이에요?', '66209150a0774b0beae3014ff9d11432a46f239062a75e3f08fcea36af8c554b'),
    (4222, 51, 3, 222, 'No, that''s all for now.', '아니요, 지금은 그게 다예요.', 'You must put a sticker on fruit yourself. Do you have another problem?', '과일은 직접 스티커를 붙여 오셔야 해요. 다른 문제도 있으세요?', 'ab2f4c82c060bdb1639e11bbcef1d80a6a1f9a2091b680dc8206cc5ae970c194'),
    (4223, 51, 4, 223, 'Okay, I''ll be back very soon.', '네, 금방 돌아올게요.', 'I will watch your things. Can you get the sticker?', '제가 손님 물건을 봐드릴게요. 스티커 받아오실 수 있어요?', '6bc28e29663b2ed89ae40e57711f39ae8b454f3e904469edd1075012d305d536'),
    (4224, 51, 5, 224, 'I was trying to scan the barcode on a bag of apples.', '사과 한 봉지 바코드를 찍으려던 참이었어요.', 'Of course, let me have a look. What were you doing when the trouble started?', '물론이죠, 한번 볼게요. 문제가 생겼을 때 뭘 하고 계셨어요?', '6e854d4e1246fe1dad5915ecf7971ad9bc39729fdc4a533960230ad249c06f64'),
    (4225, 51, 6, 225, 'It froze halfway through my shopping, right after the fruit.', '장을 보던 중간에 멈췄어요, 과일 찍고 바로요.', 'Of course, let me have a look. What were you doing when the trouble started?', '물론이죠, 한번 볼게요. 문제가 생겼을 때 뭘 하고 계셨어요?', '71611d8541534592cb75b9c2b691ddd850c6cf9867f29e9d93934d0f87d9bc44'),
    (4226, 51, 7, 226, 'The screen still shows an error, so could you check it?', '화면에 아직 오류가 떠 있는데, 한번 확인해 주시겠어요?', 'Ah, I see. Fruit needs a special sticker before you pay. Is anything else giving you trouble?', '아, 그렇군요. 과일은 계산 전에 따로 스티커가 필요해요. 또 불편한 점이 있으세요?', '91e8aff50039d55791a932772ac5db5602ddf33f69c9b320ed03ac64023d7af0'),
    (4227, 51, 8, 227, 'Sure, I''ll run back to the fruit section and get one.', '네, 과일 코너로 얼른 다시 가서 받아올게요.', 'Don''t worry, your things are safe with me here. Could you quickly go and get that sticker?', '걱정 마세요, 손님 물건은 제가 여기서 지키고 있을게요. 얼른 가서 그 스티커를 받아오시겠어요?', '64015c736f17ce73c48ecc4a332734325b5162b86c3d452152e738abd98cee8a'),
    (4228, 51, 9, 228, 'The screen froze while I was scanning my items.', '물건 찍는 중에 화면이 멈춰버렸어요.', 'Sure, let me take a look — this machine acts up all the time. What happened exactly?', '네, 한번 볼게요 — 이 기계가 원래 말썽이 잦아요. 정확히 어떻게 된 거예요?', '0f1d40f4c9c1ea73d4485580525db2053167be364374cfcf2c144148ae49d595'),
    (4229, 51, 10, 229, 'Okay, I''ll go right now — it won''t take long.', '네, 지금 바로 갔다 올게요 — 금방이면 돼요.', 'I''ll watch your things while you go. Could you quickly pop over and grab the sticker?', '다녀오시는 동안 제가 고객님 물건 지키고 있을게요. 얼른 가서 스티커 받아 오실래요?', '10708f510b20624e286d7d4cd6caf5e5e342ada9d6024020d58511b540e9ed14'),
    (4230, 43, 1, 230, 'The action one, please.', '액션 영화로 주세요.', 'We have an action movie and a cartoon tonight. Which one?', '오늘 밤엔 액션 영화랑 만화 영화가 있어요. 어떤 거요?', 'f8dc58b54079ae7e80c4d25d5b523cfaa35de181d9139d059c4a540b30504522'),
    (4231, 43, 2, 231, 'Just one ticket, please.', '한 장만 주세요.', 'How many tickets?', '몇 장 드릴까요?', 'a6bcb04068d094b8816ab361044a6d72f05cfa273943734d466edde5b6e833e0'),
    (4232, 43, 3, 232, 'At nine o''clock, please.', '9시로 주세요.', 'We have seven or nine o''clock. How many tickets?', '7시랑 9시가 있어요. 몇 장 드릴까요?', '473418aff5d2aa0c31c32906575a28bbcb1657a5fc3bb7b469207662fc8c90dc'),
    (4233, 43, 4, 233, 'I always eat popcorn at movies.', '저는 영화 볼 때 항상 팝콘을 먹어요.', 'Do you want popcorn or a drink?', '팝콘 드릴까요, 음료 드릴까요?', '778cafa0b77a54caf854b7be9604308239d933587963c6609e73f725bcf19ab1'),
    (4234, 43, 5, 234, 'I can''t decide. Which one is more popular?', '고르기가 어렵네요. 어느 쪽이 더 인기 있어요?', 'We''re showing an action movie and an animated one tonight. Which one sounds better to you?', '오늘 밤엔 액션 영화랑 애니메이션 한 편을 상영해요. 어느 쪽이 더 끌리세요?', 'c2dee10af19de9cf9618451eff2cb136d4370d8b7223bde59070320d4de5d130'),
    (4235, 43, 6, 235, 'I''ll go with the later show, then.', '그럼 늦은 시간 상영으로 할게요.', 'The seven o''clock is almost full. The nine o''clock still has plenty of good seats — which works better?', '7시는 거의 차 있어요. 9시는 좋은 자리가 아직 많은데, 어느 쪽이 더 나으세요?', '5bc38726db003efcf0a5283201041779f0157298bdbdcfc688316bf7ffa0be60'),
    (4236, 43, 7, 236, 'Then I''d rather wait and get a better seat.', '그러면 기다렸다가 더 좋은 자리에 앉는 게 낫겠어요.', 'The seven o''clock is almost full, so you''d be sitting up front. Which works better?', '7시는 거의 차서 앞쪽에 앉으셔야 해요. 어느 쪽이 더 나으세요?', 'd108b5dcf7846b5ecf9eeff6b4e6778dbb796f818aacd805e77c3a8951124b3c'),
    (4237, 43, 8, 237, 'I usually grab a snack before the movie starts.', '저는 보통 영화 시작 전에 간식을 하나 사요.', 'We have all kinds of snacks here — what do you like to have during a movie?', '스낵도 여러 가지 있는데, 영화 볼 때 뭘 드시는 걸 좋아하세요?', 'b04d5dd325a28da9aceb5aed1a16b209c457908c18586e59958ef25491b90dea'),
    (4238, 43, 9, 238, 'I thought I''d catch a movie after work.', '퇴근하고 영화나 한 편 보려고요.', 'Hi there — what can I get for you tonight?', '어서 오세요 — 오늘 저녁은 뭘 도와드릴까요?', 'bc87cc0fab579aab189941da48a5dc851247fc229f3d31c33bc73f68c7cca3bf'),
    (4239, 43, 10, 239, 'I''d rather sit toward the back, so the nine o''clock, please.', '뒤쪽에 앉고 싶어서요, 9시로 할게요.', 'The seven o''clock is almost full, so you''d be sitting near the front. The nine o''clock still has plenty of good seats. Which works better for you?', '7시는 거의 차서 앞쪽 자리만 남았고, 9시는 좋은 자리가 많이 남아 있어요. 어느 쪽이 나으세요?', '874b1758e2acf1429db4ad7fedc61e83d97c92a87a42ed8395a11644a8596df7'),
    (4240, 43, 11, 240, 'Oh, is it any good? I haven''t heard much about it.', '오, 그거 괜찮아요? 얘기를 별로 못 들어서요.', 'We''ve got an action movie and an animated one showing tonight — how about the animated one?', '오늘은 액션 하나랑 애니메이션 하나가 상영 중이에요 — 애니메이션 쪽은 어떠세요?', 'efce322f7bf56a384918786d6d905009c3f63c3932255d12ee915b76a9fd00ed'),
    (4241, 57, 1, 241, 'I like the home team.', '저는 홈 팀을 좋아해요.', 'Your seat is that way. Which team do you like?', '자리는 저쪽이에요. 어느 팀을 좋아하세요?', '457c59a35989b257f478cd92f4b1c6588ccb654a848453554b8f0dd0e1df7b29'),
    (4242, 57, 2, 242, 'Where is the big screen?', '큰 화면은 어디에 있어요?', 'Is this your first game? Ask me anything.', '경기장은 처음이세요? 뭐든 물어보세요.', 'cdbf136c8e38f781bd3eab8ee535a22acd34f0cd4aaed82b452e8ceaf9ff0f41'),
    (4243, 57, 3, 243, 'Okay, I will try one.', '좋아요, 하나 먹어 볼게요.', 'People here eat meat pies. Do you want one?', '여기 사람들은 미트 파이를 먹어요. 하나 드실래요?', '77ebff2f0f4413712a982d02536ccd484e40f1cd3782dd10b3f851312bc83b51'),
    (4244, 57, 4, 244, 'Yes, one for me, please.', '네, 저는 하나 주세요.', 'Do you want one?', '하나 드실래요?', '61a5e06ba816e6bd1397e5cb6827620604feb824466b3518ca85a4cbf68231f2'),
    (4245, 57, 5, 245, 'I grew up near here, so I hope United wins tonight.', '제가 이 근처에서 자라서, 오늘 밤엔 유나이티드가 이기면 좋겠어요.', 'Here''s your seat — up those stairs in block C. So which team are you here for today?', '자리는 여기예요 — 저 계단 위 C구역이요. 그래서 오늘은 어느 팀 때문에 오셨어요?', 'bd4d79a4316ba74c3a21569c62ff2d7ddfa1b4cd76cb657abdfe4addb93f6047'),
    (4246, 57, 6, 246, 'Yes, it is. What happens when someone scores?', '네, 처음이에요. 누가 득점하면 어떻게 되나요?', 'Is this your first match here? Is there anything you want to know before it starts?', '여기 경기장은 처음이세요? 시작하기 전에 알고 싶은 게 있으세요?', '8c5e7f1298d502b2c64753831540dc60c72f79384f79a1069e5f08f31a0bede2'),
    (4247, 57, 7, 247, 'That sounds good. Is the food stand near our block?', '좋네요. 매점이 저희 구역 가까이에 있어요?', 'At halftime most fans eat a meat pie here. Would you like one?', '하프타임에는 여기 팬들 대부분이 미트 파이를 먹어요. 하나 드시겠어요?', '3ac70a7bd020febf17ddcca13695e628acf95689010bab3463fbbbf1f6424dd5'),
    (4248, 57, 8, 248, 'I''ve never had one, but it sounds worth trying.', '한 번도 먹어 본 적은 없는데, 한번 먹어볼 만하겠네요.', 'Most fans eat a meat pie here. Would you like one?', '여기 팬들 대부분이 미트 파이를 먹어요. 하나 드시겠어요?', '71e5a03090eb2f29c31ece99f97be7a4670366d019b86c6712890ef1aa81940b'),
    (4249, 57, 9, 249, 'I support the team in red — my cousin''s a big fan.', '저는 빨간 유니폼 팀 응원해요 — 사촌이 열성 팬이거든요.', 'You''re up those stairs, block C. So, which team are you here to cheer for today?', '저 계단 위 C구역이에요. 그래서, 오늘 어느 팀 응원하러 오셨어요?', 'fa791d68fdc4bd638fb27601e8d082e173a1c30308f35c4a32e45104acf2d7d1'),
    (4250, 57, 10, 250, 'Sure, I''ll just sing along once I catch the words.', '그럼요, 가사만 들리면 그냥 따라 부를게요.', 'When we score, everyone jumps up and sings — the words are up on the big screen. Will you join in with us?', '골이 들어가면 다들 일어나서 응원가를 불러요 — 가사는 전광판에 나와요. 같이 부르실래요?', '71dade015b12e9d4f3e1fe1d7bcceb625ee22b8f1e85d69ce2bbe363e8c5a4c6'),
    (4251, 57, 11, 251, 'A meat pie? If it''s a local specialty, I can''t skip it.', '미트 파이요? 여기 명물이라면 안 먹고 갈 수 없죠.', 'At halftime everyone grabs a meat pie — it''s tradition. Fancy trying one?', '하프타임엔 다들 미트 파이를 먹어요 — 전통이거든요. 하나 드셔보실래요?', 'ae24974f332c5dd07471dc44605894fc0579e5d6fb7a660a29431947ca6d33dc'),
    (4252, 68, 1, 252, 'It''s a gift for my mother.', '저희 엄마한테 줄 선물이에요.', 'What is in the box?', '상자 안에 뭐가 들어 있어요?', '282260282719543d7d3117a241236daaac580158460a023d3298a0ca0c177484'),
    (4253, 68, 2, 253, 'It can break very easily.', '그건 아주 쉽게 깨져요.', 'What is in the box?', '상자 안에 뭐가 들어 있어요?', 'ccee041deac89a84bb95db703d06bb10634dd65042ff4a0b83f38cad523b90ad'),
    (4254, 68, 3, 254, 'I can wait for slow mail.', '느린 우편도 기다릴 수 있어요.', 'Do you want fast mail or slow mail?', '빠른 우편으로 보내시겠어요, 느린 우편으로 보내시겠어요?', '3f01e9e4c86cb061c06686693fa77d98367fa669bb35eca9b06e407e74c10147'),
    (4255, 68, 4, 255, 'Yes, please keep it safe.', '네, 안전하게 지켜 주세요.', 'Do you want insurance for four pounds?', '4파운드짜리 보험을 넣으시겠어요?', '18c9455caaed3f9e9c5fd3baa511b628664fbb46ac056cb6e2cfc8c265524955'),
    (4256, 68, 5, 256, 'There''s a mug inside, so please wrap it carefully.', '안에 머그컵이 있어서요, 조심해서 포장해 주세요.', 'What''s in the package? Is there anything I should be careful with?', '소포 안에 뭐가 들어 있어요? 조심해야 할 물건이 있나요?', 'a797e8782c9cff7d12915de11e248ab33ecd8cdf2c0530a4554b2a6cf1ebe53a'),
    (4257, 68, 6, 257, 'It needs to get there by next Friday, so express, please.', '다음 주 금요일까지는 도착해야 해서 특급으로 해 주세요.', 'Express takes about a week for 25 pounds, and standard takes three weeks for 12. How soon do you want it delivered?', '특급은 일주일에 25파운드, 일반은 3주에 12파운드예요. 얼마나 빨리 도착하면 좋겠어요?', '0a514e6eee5acada7f452d24acf9a690ae1875541ec315dfb0916130a3d3afa8'),
    (4258, 68, 7, 258, 'A week? That''s fast enough for me.', '일주일이요? 저한테는 충분히 빨라요.', 'Express takes about a week for 25 pounds. How soon do you want it delivered?', '특급은 일주일에 25파운드예요. 얼마나 빨리 도착하면 좋겠어요?', 'eed185d1dd34b698a67a6e8ab5997cfa1d59452683d0be2981a12fdb65a21114'),
    (4259, 68, 8, 259, 'The books inside are worth about thirty pounds.', '안에 있는 책들은 대략 30파운드쯤 해요.', 'Would you like to add insurance for four pounds? I also need to write down the value of the items.', '4파운드에 보험을 추가하시겠어요? 그리고 물건 가치도 적어야 해요.', '8e09dc16c4b4a5ca825b88d9d8c0269b7d3d701c8ad315e142a04b8c81bfded3'),
    (4260, 68, 9, 260, 'There are teacups inside, so it''s quite fragile.', '찻잔이 들어 있어서 꽤 깨지기 쉬워요.', 'What''s in the package?', '안에 뭐가 들어 있어요?', '6a9843ee687cc187f0f5f93bef7bd8d54c660d93650e827bf5fc0ec9813f7f93'),
    (4261, 68, 10, 261, 'Yes — could I get a tracking number for it?', '네 — 운송장 번호를 받을 수 있을까요?', 'That''s everything sorted, then — anything else you need before I send it off?', '그럼 준비는 다 됐어요 — 보내기 전에 더 필요하신 거 있으세요?', 'a7b0156b4562119a0b3eb5e780197fa2a506f852c90ac4fb63cb133c113f2c75'),
    (4262, 68, 11, 262, 'About forty pounds — I hope it clears customs quickly.', '40파운드 정도요 — 세관을 빨리 통과하면 좋겠네요.', 'About how much is everything worth?', '내용물이 대략 얼마 정도 가치예요?', '1e45be149f4bddc93ae02310e8fa73fdc684e9a760ecb61d8609cec296417977'),
    (4263, 49, 1, 263, 'I usually drink light beer.', '저는 보통 가벼운 맥주를 마셔요.', 'Yes, you order here. Light beer or dark beer?', '네, 여기서 주문하시면 돼요. 가벼운 맥주요, 진한 맥주요?', 'd5d630021dcb3dbb70bd0970818a5a426a386a6e650cc1da3913d15c3b8d143a'),
    (4264, 49, 2, 264, 'The small one, please, with no ice.', '작은 걸로 주세요, 얼음은 빼고요.', 'Okay! A pint is bigger. Do you want a pint or a half?', '네! 파인트가 더 커요. 파인트로 드릴까요, 하프로 드릴까요?', '219575ba906b486ab4c00dd622d6d05d1f3b10f778a8050fa4a5e7cfa5dea73d'),
    (4265, 49, 3, 265, 'Here is my card for the beer.', '맥주값이요, 여기 제 카드요.', 'That is twelve pounds. Do you want to pay now or later?', '12파운드예요. 지금 계산하실래요, 나중에 하실래요?', '2d887b35578a5c750ccb08ddc7cb0ac99e70319ed3e3adcfbabe7a73c152ab3a'),
    (4266, 49, 4, 266, 'I will pay at the end.', '나갈 때 마지막에 계산할게요.', 'Do you want to pay now or later?', '지금 계산하실래요, 나중에 하실래요?', 'd78275b9507a19b1b028d6982c4e6bc8255ed84cb9321f6fea1770cab0b5f46e'),
    (4267, 49, 5, 267, 'Back home we drink a lot of soju.', '저희 나라에서는 소주를 많이 마셔요.', 'Yes, you order and pay here at the bar first. Tell me what you normally drink and I''ll find you something similar.', '네, 펍에서는 여기 바에서 먼저 주문하고 계산해요. 평소에 어떤 걸 드시는지 말씀해 주시면 비슷한 걸로 찾아드릴게요.', '1e7b60e04275973b3af5e55d73c8eba06210be51084bd0d349539117cf8c8611'),
    (4268, 49, 6, 268, 'I''d like something light, not too strong.', '가벼운 걸로 주세요, 너무 센 건 말고요.', 'Yes, you order and pay here at the bar first. Tell me what you normally drink.', '네, 펍에서는 여기 바에서 먼저 주문하고 계산해요. 평소에 어떤 걸 드시는지 말씀해 주세요.', '296de88acb3f489b2b5925068f4cc6083f07fbc926c8760d633a38adf4541401'),
    (4269, 49, 7, 269, 'I''ve never tried fish and chips, so let''s do that.', '피시앤칩스는 먹어 본 적이 없어서, 그걸로 할게요.', 'Good choice — pint or half? Our fish and chips is famous, if you''re eating.', '잘 고르셨어요. 파인트로 드릴까요, 하프로 드릴까요? 식사도 하신다면 여기 피시앤칩스가 유명해요.', '6e812f00b66ff74aa454c4a2df7b8dc0bd17407d91536d55e6b60691f31c81a6'),
    (4270, 49, 8, 270, 'We''ll pay all together when we leave.', '저희는 나갈 때 한꺼번에 계산할게요.', 'That''s twelve pounds forty. You can pay each time, or leave your card and pay for everything when you leave — which do you prefer?', '12파운드 40이에요. 주문할 때마다 계산하시거나, 카드를 맡겨두고 나가실 때 계산하실 수도 있어요. 어느 쪽이 좋으세요?', '4e819870793a9bc7cee2f519deba55c61ca990e9a5fc67b0bb49847535ab7a7c'),
    (4271, 49, 9, 271, 'Usually lager — what do you have on tap?', '주로 라거요 — 생맥주는 뭐가 있어요?', 'So, what do you usually drink?', '평소엔 어떤 술 드세요?', '547f2c99ac0828cd9b2613833f24b3db3c9893c317e8ea405f73b2485077d6ca'),
    (4272, 49, 10, 272, 'Yes — I''ll have the fish and chips, please.', '네 — 피시앤칩스로 할게요.', 'Are you eating? The fish and chips here is famous.', '식사도 하실 거예요? 여기 피시앤칩스가 유명해요.', '2f95bafb9f1eaff83205f96e631fc2f5cb32437de939f07e1d173f7afd3f0d1b'),
    (4273, 49, 11, 273, 'I''ll be here a while, so let''s start a tab.', '좀 오래 있을 거라, 탭으로 할게요.', 'You can pay as you go, or leave your card with me and settle up on the way out. How would you like to do it?', '주문하실 때마다 계산하셔도 되고, 카드를 맡겨두셨다가 나가실 때 한 번에 계산하셔도 돼요. 어떻게 하시겠어요?', '6f4bc75896ee941251209a693a07eac0bc51c0771d77c184134b94fabd62d05b'),
    (4274, 53, 1, 274, 'Strong tea, please, with a little milk.', '진한 차로 주세요, 우유 조금 넣어서요.', 'What kind of tea do you like? I can help.', '어떤 차 좋아하세요? 제가 도와드릴게요.', 'bce5bba0fadbeaff4c7c2aa7ae2b5ba29caa88f1d3d2c48b26b51bc6fcd57b9c'),
    (4275, 53, 2, 275, 'I want something sweet with my tea.', '차랑 같이 달콤한 걸 먹고 싶어요.', 'What kind of tea do you like?', '어떤 차 좋아하세요?', '78714a6b58e97408f56d1aa706402056c93d305e6d2619d3b429a7455a4d6892'),
    (4276, 53, 3, 276, 'I put cream first, then the jam.', '저는 크림을 먼저 바르고, 그다음에 잼을 발라요.', 'The scones come with cream and jam. Which goes first?', '스콘은 크림이랑 잼이 같이 나와요. 어떤 걸 먼저 바르세요?', '43f9838a96b0113f5afdd8820ca77137bcd89dabe937729b9e4c0bf89c82bd5a'),
    (4277, 53, 4, 277, 'Yes, one more cup would be lovely.', '네, 한 잔 더 주시면 좋겠어요.', 'Your cup is empty. Would you like more tea?', '잔이 다 비었네요. 차 더 드릴까요?', 'e4b6bd9961c68882e99893b291639a75fcbda12a3ab2249312d55ce6d6f020f0'),
    (4278, 53, 5, 278, 'I prefer something floral, especially in the afternoon.', '저는 꽃향이 나는 걸 더 좋아해요, 특히 오후에요.', 'What kind of tea do you usually enjoy — floral, strong, or fruity? If it''s your first time, I can recommend a few.', '평소 어떤 차를 즐기세요 — 꽃향, 진한 맛, 과일향? 처음이시면 몇 가지 추천해드릴게요.', '016b96dddead88c8f386a5cfb41bbd880d88606b16e6d304bd4433624a6f0ffe'),
    (4279, 53, 6, 279, 'I spread jam on the scone before the cream.', '저는 크림보다 잼을 스콘에 먼저 발라요.', 'The scones come with clotted cream and jam. Do you put jam first or cream first? I can show you how we do it here.', '스콘은 클로티드 크림과 잼이 같이 나와요. 잼을 먼저 바르시나요, 크림을 먼저 바르시나요? 저희가 먹는 방법을 알려드릴게요.', '62b5b08bf633357bdd85adacf6dc9898dbe819eded403c35556eb05b3a94c017'),
    (4280, 53, 7, 280, 'Please show me the traditional way of doing it.', '전통적인 방식으로 하는 법 좀 알려 주세요.', 'The scones come with clotted cream and jam. I can show you how we do it here.', '스콘은 클로티드 크림과 잼이 같이 나와요. 저희가 먹는 방법을 알려드릴게요.', '8373c85c4e972551bf9021a1f7e145f25dfe9426248b01c214b4e03a01dcda25'),
    (4281, 53, 8, 281, 'It''s lovely, but I''d like to try a different one.', '맛있었어요, 근데 이번엔 다른 걸로 마셔 보고 싶어요.', 'How is everything so far? Would you like a refill — the same one, or shall I bring the menu again?', '지금까지 어떠세요? 리필해드릴까요 — 같은 걸로 드릴까요, 메뉴를 다시 가져다드릴까요?', 'ae4cb4cd11ea8cf2ffab4d665b73c4cab31e98399066fb33f0073af99fbd066d'),
    (4282, 53, 9, 282, 'Something floral — what would go well with the scones?', '꽃향이요 — 스콘이랑 잘 어울리는 게 뭘까요?', 'What kind of tea do you usually enjoy — floral, strong, fruity?', '평소 어떤 차를 즐기세요 — 꽃향, 진한 맛, 과일향?', '09453e92e8b781b39839940e3fc7a6ff62d324440d6593f6b1a7bf445ef11324'),
    (4283, 53, 10, 283, 'It''s lovely — can I get a refill of the same tea?', '너무 좋아요 — 같은 차로 리필받을 수 있을까요?', 'How is everything? Is there anything else I can bring you?', '어떠세요, 입에 맞으세요? 더 가져다드릴 것 있을까요?', 'bdcb146e8368bff29d1e7c895d14bcf9e049dd0e0d52e7a931bffc6c81be669f'),
    (4284, 53, 11, 284, 'A pot of Earl Grey, please — I''d like to take my time.', '얼그레이 한 주전자 주세요 — 천천히 즐기고 싶어서요.', 'Right then — which tea would you like?', '그럼 — 어떤 차로 드릴까요?', '3712383bd114b0e03eff2aa7600f60a03063598e9b87db0444af518325799d9a'),
    (4285, 61, 1, 285, 'Just the same style as last time, please.', '지난번이랑 똑같은 스타일로 해 주세요.', 'Hi, welcome! What do you want for your hair today?', '안녕하세요, 어서 오세요! 오늘 머리 어떻게 해드릴까요?', 'b3599adefc0cc437d72c86856dcc45fc169a941a78f80a9ec6ab8e2024212057'),
    (4286, 61, 2, 286, 'Just a little shorter, about two centimeters.', '조금만 짧게요, 2센티미터 정도요.', 'How much should I cut?', '얼마나 자를까요?', '18609cda5823890d951dd3e0d3153577263353cd751aaed71f9817647c62136c'),
    (4287, 61, 3, 287, 'Please trim the front too, about one centimeter.', '앞머리도 1센티미터 정도 다듬어 주세요.', 'How much should I cut, and your bangs too?', '얼마나 자르고, 앞머리도 다듬을까요?', '3fc992d48ca5639213185570d732396915a2ac48437ac375f07cf0ba66d83b55'),
    (4288, 61, 4, 288, 'Thank you so much, it is perfect.', '정말 감사해요, 딱 좋아요.', 'All done! Do you like it?', '다 됐어요! 마음에 드세요?', '8c48ed5c2274d9dca4dc4df91a506218975bb14287f891697a15aec31d0dfd5b'),
    (4289, 61, 5, 289, 'I''d like something different, but nothing too dramatic.', '좀 다른 스타일로 하고 싶은데, 너무 확 바꾸진 말아 주세요.', 'Hi, welcome in! What would you like me to do with your hair today?', '안녕하세요, 어서 오세요! 오늘 머리 어떻게 해드릴까요?', '61df637bbc5c193ae8972730c0522448b6d69b8a8595dd23e0eb88cbbdabd4ab'),
    (4290, 61, 6, 290, 'Could you add some layers around my face?', '얼굴 쪽으로 층 좀 내 주실 수 있어요?', 'What would you like me to do with your hair today?', '오늘 머리 어떻게 해드릴까요?', '22c5c65aee659a60065c0f4375f3543273ece73c36065d8c06b4a4ab309190ab'),
    (4291, 61, 7, 291, 'I''d like to keep the length and just tidy the ends.', '길이는 그대로 두고 끝만 다듬어 주세요.', 'How much should I cut off? And do you want me to do the front as well?', '길이는 얼마나 자를까요? 그리고 앞머리도 같이 해드릴까요?', '759f8ed3c27c26abcecdc58703ee162345fb524c3643bd402f5b210bef5660b6'),
    (4292, 61, 8, 292, 'It''s exactly what I wanted, thank you so much.', '딱 제가 원하던 거예요, 정말 감사해요.', 'All done — take a look! How does it look to you, and is there anything you''d like me to fix?', '다 됐어요, 한번 보세요! 어떠세요? 더 고쳤으면 하는 데 있으세요?', '35020a9d644c05e3f615aab1999604ce560e7b4d444e70398f66b4a1772100ea'),
    (4293, 61, 9, 293, 'Nothing big — I just want to get a trim.', '크게 하는 건 아니고요 — 그냥 좀 다듬으려고요.', 'Hi, welcome in! So what are we doing with your hair today?', '어서 오세요! 오늘 머리 어떻게 해드릴까요?', '5455346130bad72280aebb9a4c1967fc146ffd35f764210ad8f31ca32b1cc14e'),
    (4294, 61, 10, 294, 'Could you thin it out? It feels really heavy.', '숱 좀 쳐주실래요? 너무 무거운 느낌이에요.', 'Got it. And is there anything else you''d like me to do while I''m at it?', '알겠어요. 그리고 하는 김에 더 해드렸으면 하는 거 있으세요?', 'a7f0cf308666f5a2a19b21110b47b0793e2549513f51dd8a39cb84719165d24e'),
    (4295, 61, 11, 295, 'No thanks — I''m growing them out.', '아니요 — 앞머리는 기르는 중이라서요.', 'Do you want me to trim your bangs while I''m at it?', '하는 김에 앞머리도 다듬어드릴까요?', '5397832ff1bc3841680bce0d3afe36c1280c80a8fa4934e232665690cdadabf6'),
    (4296, 63, 1, 296, 'Yes, I''d like that.', '네, 그거 좋아요.', 'That team needs one more person. Do you want to play?', '저 팀에 한 명이 더 필요해요. 같이 하실래요?', '3149df0fbf6a6c3ccd840a5e816f25da1750114ceb09d5a60ddc32f6d5de5797'),
    (4297, 63, 2, 297, 'I can play with them tonight.', '오늘 밤에 저 같이 할 수 있어요.', 'Do you want to play?', '같이 하실래요?', '8d6e0b54a372dfd3d2b0b7239521097be1ad3c321ca79c08d0dda695006f3342'),
    (4298, 63, 3, 298, 'I know a lot about music.', '저는 음악을 많이 알아요.', 'The quiz has music and sports. Which one is easy for you?', '퀴즈에 음악이랑 스포츠가 나와요. 어떤 게 쉬우세요?', '3645348ed0a44095a07d43483d34a2bd91aa9bd93662ae81d15796e5ce98dfab'),
    (4299, 63, 4, 299, 'Let''s call it The Quiz Cats.', 'The Quiz Cats라고 해요.', 'Now we need a team name. What is your idea?', '이제 팀 이름이 필요해요. 어떤 생각이 있으세요?', '06ad926f3179635dc390ae991f2134b4610dead221e430f3e407700465658294'),
    (4300, 63, 5, 300, 'Sure, I''d love to join a team tonight.', '좋아요, 오늘 밤에 팀에 들어가고 싶어요.', 'Quiz night starts soon and that team is one person short. Would you like to play with them?', '퀴즈 나이트가 곧 시작하는데 저 팀에 한 명이 부족해요. 같이 하시겠어요?', 'a1864f70b5fbbccdb3fe282eeb3259f1c331ab7ab995a9403198326c0decd067'),
    (4301, 63, 6, 301, 'My strong point is music, so I''ll take those questions.', '제 강점은 음악이라서 그쪽 문제를 맡을게요.', 'The topics are music, sports, and general knowledge. Which one suits you best?', '주제는 음악, 스포츠, 상식이에요. 어떤 게 제일 잘 맞으세요?', 'b55332fc4f5e478184b9dbeb4a42d4932522ed55603dc29528ac2241df5aa529'),
    (4302, 63, 7, 302, 'Give me a minute to think of a name.', '이름 하나 생각해 볼 테니 잠깐만요.', 'Entry is two pounds, and the winning team drinks free. So, what name should your team use?', '참가비는 2파운드고, 우승한 팀은 음료가 공짜예요. 자, 팀 이름은 뭐로 할까요?', '5138b912c50988781b3eb24b8d6dccbd8bc1848554e3bcca34351ca0247c9765'),
    (4303, 63, 8, 303, 'Let''s go with The Pub Owls, then.', '그럼 The Pub Owls로 정해요.', 'So, what name should your team use?', '자, 팀 이름은 뭐로 할까요?', '88a8c7394528cca405cfad6f473d9ffc0bc19af6d5a16d39d7be4c3979b33a27'),
    (4304, 63, 9, 304, 'Sure, I''d love to join in — sounds fun!', '좋아요, 저도 낄게요 — 재밌겠는데요!', 'Hey, are you here on your own? Quiz night''s about to start and that team over there needs one more — what do you say?', '저기, 혼자 오셨어요? 퀴즈 나이트가 곧 시작하는데 저쪽 팀에 한 명 모자라요 — 어떠세요?', '04bade844b5491e03cd70ecafb0d24ebfafe8519e31900ae6f6d1993edebb13e'),
    (4305, 63, 10, 305, 'Never, but I''ll give it a go!', '한 번도요, 근데 한번 해볼게요!', 'Quiz night''s about to start — have you ever done a pub quiz before?', '퀴즈 나이트가 곧 시작해요 — 펍 퀴즈 해보신 적 있어요?', '48d60941f9aaaf42d7f83d2f80c16f1c930e7ebdf2294d7ed28930727d732b5b'),
    (4306, 63, 11, 306, 'I know a thing or two about music, so I''ll take that round.', '음악은 좀 알아서요, 그 라운드는 제가 맡을게요.', 'The rounds are music, sports, and general knowledge. What are you good at?', '라운드는 음악, 스포츠, 상식이에요. 어떤 분야에 자신 있어요?', '774007fa36d154fa710a991d44d20b7b37afc9cd2a8e2c07d0f6110afd9b117b'),
    (4307, 69, 1, 307, 'I took the bus and then the subway.', '버스를 타고 나서 지하철을 탔어요.', 'Let me check your card. How did you travel today?', '카드를 확인해 볼게요. 오늘 어떻게 다니셨어요?', '6925709cde42fc32c776775bc0a776706d3fd67346da74b13fa1df70263c80c9'),
    (4308, 69, 2, 308, 'So I can get my money back?', '그럼 돈을 돌려받을 수 있는 거죠?', 'You paid too much. I will return the extra money.', '요금이 과하게 부과됐네요. 차액은 돌려드릴게요.', '3df5b7a5be51f8d8002349abe3fc4f219dd66831cf67f625f8b75dfdd6207397'),
    (4309, 69, 3, 309, 'I am here for three more days.', '저 여기 사흘 더 있어요.', 'You can buy a day pass.', '원데이 패스를 사실 수 있어요.', '4162ddc707a8663724329737fc64be781237736b2087c2821bc9dd72a0c2f83b'),
    (4310, 69, 4, 310, 'I ride every day, morning and evening.', '매일 타요, 아침저녁으로요.', 'You can buy a day pass. How often do you ride?', '원데이 패스를 사실 수 있어요. 지하철은 얼마나 자주 타세요?', '008da277396cd7ac6162b7b2c8b6a3cbaf67370b597d0aa89b0b063544c93879'),
    (4311, 69, 5, 311, 'I came from Green Park and had to transfer to Line 2.', '그린파크에서 왔는데 2호선으로 갈아타야 했어요.', 'What''s the problem? Tell me how you traveled today, and I''ll look at your card.', '무슨 문제세요? 오늘 어떻게 이동하셨는지 말씀해 주시면 카드를 살펴볼게요.', '8466476d13e774d2fea5655e82fab116e77077cd43abd023b5deb7c4eaa380a4'),
    (4312, 69, 6, 312, 'Thanks. I need to get to King''s Cross before six.', '감사합니다. 여섯 시 전에 킹스크로스에 가야 해요.', 'You paid more than you should have. I''ll return the difference now. Where are you heading?', '원래 내셔야 할 금액보다 많이 내셨어요. 차액은 지금 돌려드릴게요. 지금 어디로 가시는 길이에요?', 'd91e4fc00ef85c3733b4f71cec115e7ea04315f6a313655ce3f4f9e9625690ae'),
    (4313, 69, 7, 313, 'I''m here until Friday and I''ll use the subway a lot.', '금요일까지 있고 지하철은 많이 탈 것 같아요.', 'How many days are you staying, and how often will you use the subway?', '며칠이나 머무르시고, 지하철은 얼마나 자주 이용하실 건가요?', '58417b91d84048fac96e8b62e55cecfa1540bfcc8b970ef21094ff4f5bf09e41'),
    (4314, 69, 8, 314, 'If the pass saves money, it''s worth it for me.', '패스로 돈이 아껴진다면 저한테는 그만한 값어치가 있죠.', 'How many days are you staying, and how often will you use the subway? There may be a cheaper option for you.', '며칠이나 머무르시고, 지하철은 얼마나 자주 이용하실 건가요? 더 저렴한 방법이 있을 수도 있어요.', 'b52043dab7485958788b5579cb23f7d51232e5f33ed08fe6c9f055e7dd9bfa6d'),
    (4315, 69, 9, 315, 'I tapped in at King''s Cross, but the gate beeped when I tapped out.', '킹스크로스에서 찍고 탔는데, 내릴 때 찍으니까 게이트에서 경고음이 났어요.', 'Walk me through how you''ve been traveling today, and I''ll check your card.', '오늘 어떻게 이동하셨는지 설명해 주시면 카드를 확인해볼게요.', '32beafb29a59fad5a3cec359c4450fd633a46a674ea12dbc45f59f1e42362a84'),
    (4316, 69, 10, 316, 'I think I was overcharged — five pounds for one short ride.', '요금이 과다 청구된 것 같아요 — 잠깐 탔는데 5파운드나 나왔어요.', 'What seems to be the trouble? Take your time.', '무슨 문제세요? 천천히요.', 'efa38bf7a28112aae9afce86b11e1926ba5c64c90ffb802a904d03a8c02a0705'),
    (4317, 69, 11, 317, 'I''ll be riding a few more days, mostly off-peak — is that cheaper?', '며칠 더 탈 건데 거의 붐비는 시간은 피해서 타요 — 그럼 더 싼가요?', 'How much longer are you in London, and how often will you be riding?', '런던에 며칠 더 계세요? 지하철은 얼마나 자주 타실 것 같아요?', '641258893bb5c98bfdf530b467e3075583607a805180080cb88aea94639179a5'),
    (4318, 66, 1, 318, 'I have two hours before lunch.', '점심 전까지 두 시간 있어요.', 'I can show you a good hiking path! How many hours can you walk today?', '좋은 하이킹 코스 추천해드릴게요! 오늘 몇 시간 걸으실 수 있어요?', 'c4725cc299eb2a7989232879cb4e950cb31ee8900daf208d144375f6439f25a4'),
    (4319, 66, 2, 319, 'The lake path is an easy walk.', '호수 길이 쉬운 산책길이죠.', 'It may rain later. Lake path or hill path?', '이따 비가 올 수도 있어요. 호수 길이요, 언덕 길이요?', 'f518bf72f90badb36b375868da25d4e8b6a8bc3dbac83973d056062f96d11e46'),
    (4320, 66, 3, 320, 'I have water and snacks with me.', '물이랑 간식을 가지고 있어요.', 'Good choice! What is in your bag today?', '잘 고르셨어요! 오늘 가방에 뭐가 있어요?', 'f4aefc1a623d0a2b3fd01153912902900adb1cb2074f8f3fa339a3b430979c1d'),
    (4321, 66, 4, 321, 'There is a raincoat in my bag.', '가방에 우비가 있어요.', 'What is in your bag today?', '오늘 가방에 뭐가 있어요?', '5834c7188948da9ccb0ce60e364193ad4426a043d463799b718fb82ff7fa03c2'),
    (4322, 66, 5, 322, 'I go hiking about twice a month, mostly on weekends.', '한 달에 두 번쯤, 주로 주말에 하이킹을 가요.', 'Great! Do you hike a lot? And how long do you want to be out today?', '좋아요! 하이킹 많이 하세요? 그리고 오늘은 얼마나 걸을 생각이세요?', '1f4abba2c514038c3521fe5b191c329d1f310781f777630d2a939250d738db32'),
    (4323, 66, 6, 323, 'I''ll take the easy one by the lake.', '호수 쪽 쉬운 길로 갈게요.', 'There''s a flat trail around the lake, and a harder one up a hill. Which one would you prefer?', '호수를 도는 평평한 길이 있고, 좀 힘든 언덕 길이 있어요. 어느 쪽이 더 좋으세요?', '147f2ad3f7ba3425ca833a8f5123d0c694cd4e92623da3cea89062d46d612468'),
    (4324, 66, 7, 324, 'I packed a first aid kit and a torch in my backpack.', '배낭에 구급함이랑 손전등을 챙겨 왔어요.', 'Good choice. What did you bring today? I''ll tell you if something is missing.', '잘 고르셨어요. 오늘 뭘 챙겨 오셨어요? 빠진 게 있으면 알려드릴게요.', 'c6b99ad907118f5a11e7004c517716978b8451d61dfc269040905af69048373a'),
    (4325, 66, 8, 325, 'I''m not sure I have enough water for the whole walk.', '길 전체를 걷기에 물이 충분한지 모르겠어요.', 'What did you bring today? I''ll tell you if something is missing.', '오늘 뭘 챙겨 오셨어요? 빠진 게 있으면 알려드릴게요.', '87230f4b811ccb9d2a6e8885455e8e1985d11ffa1de9976f071a394d7cab079d'),
    (4326, 66, 9, 326, 'How steep is the hill route? I''m not in great shape.', '언덕길은 얼마나 가파른데요? 제가 체력이 좋진 않아서요.', 'There''s an easy lakeside loop, and a hill route with an amazing lookout. Which sounds right for you?', '쉬운 호수 둘레길이랑, 전망이 끝내주는 언덕길이 있어요. 어느 쪽이 맞을 것 같으세요?', 'a797e872127044389a36c153dc9cd337fd94ce0397f5f8f7d44dc3cfa5a803e5'),
    (4327, 66, 10, 327, 'I''ve got water and snacks, but no rain gear.', '물이랑 간식은 있는데, 비 대비 장비는 없어요.', 'Good pick. What have you got with you today — water, snacks, anything else? I''ll tell you if you''re missing anything.', '잘 고르셨어요. 오늘 뭐 챙겨 오셨어요 — 물, 간식, 또 뭐 있어요? 빠진 게 있으면 알려드릴게요.', '67f9d135cf960d2370bd2b5d7508fc6e194e0cd1ac791e2cd50b13f3f857391b'),
    (4328, 66, 11, 328, 'Not really, but I want to make it to the top today.', '자주는 아닌데, 오늘은 꼭 정상까지 가보고 싶어요.', 'Do you hike often? And what are you hoping to do today?', '하이킹 자주 하세요? 그리고 오늘은 뭘 해보고 싶으세요?', '5daa13d3c17ea320d6f9030a952902da6a7052a78da70751e4f616d0771b3850');

DO $$
DECLARE
    affected_rows INTEGER;
BEGIN
    IF (SELECT count(*) FROM lan391_representative_image_map) <> 328 THEN
        RAISE EXCEPTION 'LAN-391 representative mapping requires 328 expressions';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM lan391_representative_image_map asset
        LEFT JOIN writing_expression expression ON expression.id = asset.expression_id
        WHERE expression.id IS NULL
           OR expression.scenario_id IS DISTINCT FROM asset.scenario_id
           OR expression.display_order IS DISTINCT FROM asset.expression_display_order
           OR expression.representative_sentence_text IS DISTINCT FROM asset.sentence_en
           OR expression.representative_sentence_translation IS DISTINCT FROM asset.sentence_ko
           OR expression.representative_question_text IS DISTINCT FROM asset.question_en
           OR expression.representative_question_translation IS DISTINCT FROM asset.question_ko
           OR expression.representative_image_url IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'LAN-391 representative mapping differs from V136 or image URLs are already set';
    END IF;

    UPDATE writing_expression expression
    SET representative_image_url = 'https://d19azau1un4t7r.cloudfront.net/content/scenario-expression-representative/sha256-5af4794cc120dad8e3e897dc03117cfbcfd37125de23e8305a1e8b69fd4943f4/scenario-order-'
        || asset.scenario_id || '/sql-row-' || lpad(asset.sql_values_row::text, 4, '0')
        || '/' || asset.image_sha256 || '.webp'
    FROM lan391_representative_image_map asset
    WHERE expression.id = asset.expression_id;

    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    IF affected_rows <> 328 THEN
        RAISE EXCEPTION 'LAN-391 representative URL update affected % expressions, expected 328', affected_rows;
    END IF;
END $$;
